// Jonker-Volgenant LAP solver
// Based on the public-domain implementation by Roy Jonker (1987) / common ports.
// Dense double cost matrix, row-major, minimize.
#include <cmath>
#include <cstdint>
#include <cstring>
#include <vector>
#include <algorithm>
#include <limits>

static const double BIG = 1e18;

/*
 * Solve min-cost assignment.
 * cost: n*n row-major
 * rowsol[i] = assigned column
 * returns 0 on success
 */
extern "C" int lapjv_solve(const double* cost, int n, int* rowsol) {
    std::vector<int> colsol(n);
    std::vector<double> u(n), v(n), d(n);
    std::vector<int> pred(n), free_rows, collist(n);
    std::vector<char> todo(n);
    std::vector<int> matches(n);

    std::fill(rowsol, rowsol + n, -1);
    std::fill(colsol.begin(), colsol.end(), -1);
    std::fill(u.begin(), u.end(), 0.0);
    std::fill(v.begin(), v.end(), 0.0);

    // COLUMN REDUCTION
    for (int j = n - 1; j >= 0; --j) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double c = cost[(int64_t)i * n + j];
            if (c < minv) { minv = c; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] == -1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            colsol[j] = -1; // unassigned (row already taken)
        }
    }

    // REDUCTION TRANSFER
    std::vector<int> freelist;
    freelist.reserve(n);
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] == -1) freelist.push_back(i);
    }

    int nfree = 0;
    std::vector<int> free2;
    free2.reserve(freelist.size());

    for (int i : freelist) {
        const double* row = cost + (int64_t)i * n;
        double minv = BIG, second = BIG;
        int j1 = -1;
        for (int j = 0; j < n; ++j) {
            double red = row[j] - v[j];
            if (red < second) {
                if (red >= minv) {
                    second = red;
                } else {
                    second = minv;
                    minv = red;
                    j1 = j;
                }
            }
        }
        u[i] = minv;
        double thresh = second - minv;
        if (thresh > 1e-12) {
            int i0 = colsol[j1];
            // transfer if the current owner has slack
            if (i0 >= 0) {
                double slack_owner = cost[(int64_t)i0 * n + j1] - v[j1] - u[i0];
                // always transfer? Classic JV transfers when min < second uniquely
                // and previous assignment can be released.
                // We follow: if reduced cost gap, steal the column and free previous row
                // only if previous row's reduced cost is not strictly better.
                // Simpler reliable approach: only take column if unassigned.
                if (false) {}
            }
            if (colsol[j1] < 0) {
                colsol[j1] = i;
                rowsol[i] = j1;
            } else {
                // try to transfer: compare
                int i0 = colsol[j1];
                if (u[i0] - minv > 1e-15) {
                    // i is better? u stores min reduced. Not directly comparable across rows.
                    free2.push_back(i);
                } else {
                    free2.push_back(i);
                }
            }
        } else {
            free2.push_back(i);
        }
    }

    // AUGMENTING ROW REDUCTION (two passes) + augmentation via Dijkstra
    // Rebuild free list from current assignment
    free2.clear();
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) free2.push_back(i);

    auto augment = [&](int freerow) -> bool {
        const double* row = cost + (int64_t)freerow * n;
        double umin = BIG;
        for (int j = 0; j < n; ++j) {
            d[j] = row[j] - v[j];
            pred[j] = freerow;
            todo[j] = 1;
            if (d[j] < umin) umin = d[j];
        }
        // subtract umin so min is 0
        for (int j = 0; j < n; ++j) d[j] -= umin;

        int endofpath = -1;
        std::vector<int> ready;
        // columns with d==0 initially are candidates; we scan in Dijkstra order
        while (true) {
            double h = BIG;
            int jbest = -1;
            for (int j = 0; j < n; ++j) {
                if (todo[j] && d[j] < h) { h = d[j]; jbest = j; }
            }
            if (jbest < 0) return false;
            todo[jbest] = 0;
            int i0 = colsol[jbest];
            if (i0 < 0) { endofpath = jbest; break; }
            const double* row2 = cost + (int64_t)i0 * n;
            double base = row2[jbest] - v[jbest];
            for (int j = 0; j < n; ++j) if (todo[j]) {
                double nd = h + row2[j] - v[j] - base;
                if (nd < d[j]) {
                    d[j] = nd;
                    pred[j] = i0;
                }
            }
        }
        // dual update
        double dend = d[endofpath];
        for (int j = 0; j < n; ++j) {
            if (!todo[j]) v[j] += d[j] - dend;
        }
        u[freerow] = umin + dend;
        // update u of rows along? not strictly needed for primal
        // augment
        int j = endofpath;
        while (true) {
            int i0 = pred[j];
            colsol[j] = i0;
            int jnext = rowsol[i0];
            rowsol[i0] = j;
            if (i0 == freerow) break;
            j = jnext;
        }
        return true;
    };

    for (int i : free2) {
        if (!augment(i)) return -1;
    }
    return 0;
}
