/*
 * Modified Jonker-Volgenant dense LAP (minimize).
 * Faithful port of the algorithm used by scipy.optimize.linear_sum_assignment
 * rectangular version, specialized to square for speed, plus a k-NN sparse variant.
 *
 * Reference: Crouse, D.F. "On implementing 2D rectangular assignment algorithms"
 * IEEE TAES 2016. The JV algorithm is a well-known published method.
 */
#include <cstdint>
#include <cstring>
#include <cmath>
#include <vector>
#include <algorithm>
#include <limits>
#include <cstdio>

static constexpr double INF = 1e100;

// Returns 0 on success. rowsol[i] = column assigned to row i.
extern "C" int jv_dense(const double* C, int n, int* rowsol) {
    std::vector<double> u(n), v(n), d(n);
    std::vector<int> colsol(n, -1), pred(n), free_r;
    std::vector<uint8_t> in_tree(n);

    std::fill(rowsol, rowsol + n, -1);

    // ---- column reduction ----
    for (int j = n - 1; j >= 0; --j) {
        double m = C[j];
        int im = 0;
        for (int i = 1; i < n; ++i) {
            double c = C[(int64_t)i * n + j];
            if (c < m) { m = c; im = i; }
        }
        v[j] = m;
        if (rowsol[im] == -1) {
            rowsol[im] = j;
            colsol[j] = im;
        }
    }

    // ---- reduction transfer ----
    free_r.clear();
    for (int i = 0; i < n; ++i) if (rowsol[i] == -1) free_r.push_back(i);

    std::vector<int> still_free;
    still_free.reserve(free_r.size());
    for (int i : free_r) {
        const double* row = C + (int64_t)i * n;
        double m1 = INF, m2 = INF;
        int j1 = -1;
        for (int j = 0; j < n; ++j) {
            double r = row[j] - v[j];
            if (r < m2) {
                if (r >= m1) m2 = r;
                else { m2 = m1; m1 = r; j1 = j; }
            }
        }
        u[i] = m1;
        if (m2 - m1 > 1e-12 && colsol[j1] == -1) {
            // unique minimum and column free — but column free case already
            // handled; if column assigned, we may transfer
        }
        if (colsol[j1] == -1) {
            colsol[j1] = i;
            rowsol[i] = j1;
        } else if (m2 - m1 > 1e-12) {
            // transfer: free the previous row if its reduced cost is worse
            int i0 = colsol[j1];
            double r0 = C[(int64_t)i0 * n + j1] - v[j1];
            // u[i0] may be unset if i0 was assigned in column reduction.
            // Only transfer when previous owner was assigned in column reduction
            // (u not meaningful). Standard approach from Jonker:
            // if row i has a unique min column already taken, compare.
            // We'll just leave it free and let augmentation handle it — correct, slightly slower.
            still_free.push_back(i);
        } else {
            still_free.push_back(i);
        }
    }

    // rebuild free from assignment (in case)
    still_free.clear();
    for (int i = 0; i < n; ++i) if (rowsol[i] == -1) still_free.push_back(i);

    auto augment = [&](int f) -> bool {
        const double* row = C + (int64_t)f * n;
        for (int j = 0; j < n; ++j) {
            d[j] = row[j] - v[j];
            pred[j] = f;
            in_tree[j] = 0;
        }
        int endcol = -1;
        // low-level Dijkstra with linear scan (n=600, fine if few augmentations)
        while (true) {
            double h = INF;
            int jb = -1;
            for (int j = 0; j < n; ++j) if (!in_tree[j] && d[j] < h) { h = d[j]; jb = j; }
            if (jb < 0) return false;
            in_tree[jb] = 1;
            int i0 = colsol[jb];
            if (i0 < 0) { endcol = jb; break; }
            const double* r2 = C + (int64_t)i0 * n;
            double base = r2[jb] - v[jb];
            for (int j = 0; j < n; ++j) if (!in_tree[j]) {
                double nd = h + r2[j] - v[j] - base;
                if (nd < d[j] - 1e-15) { d[j] = nd; pred[j] = i0; }
                else if (nd < d[j]) { d[j] = nd; pred[j] = i0; }
            }
        }
        double dend = d[endcol];
        for (int j = 0; j < n; ++j) if (in_tree[j]) v[j] += d[j] - dend;
        u[f] = dend; // not exact dual, unused
        int j = endcol;
        while (true) {
            int i0 = pred[j];
            colsol[j] = i0;
            int jn = rowsol[i0];
            rowsol[i0] = j;
            if (i0 == f) break;
            j = jn;
        }
        return true;
    };

    for (int i : still_free) {
        if (!augment(i)) return -1;
    }
    // verify
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) return -2;
    return 0;
}

// Sparse JV: each row has k candidate columns (idx) with costs.
// idx: n*k int32, costs: n*k double, row-major.
// Unlisted columns treated as INF (forbidden).
extern "C" int jv_sparse(const int* idx, const double* costs, int n, int k, int* rowsol) {
    std::vector<double> v(n, 0.0), d(n);
    std::vector<int> colsol(n, -1), pred(n);
    std::vector<uint8_t> in_tree(n);
    std::fill(rowsol, rowsol + n, -1);

    // column reduction over sparse edges only, scanning all edges
    // For each column find min incoming among provided edges.
    std::vector<double> colmin(n, INF);
    std::vector<int> colarg(n, -1);
    for (int i = 0; i < n; ++i) {
        const int* id = idx + (int64_t)i * k;
        const double* cs = costs + (int64_t)i * k;
        for (int t = 0; t < k; ++t) {
            int j = id[t];
            double c = cs[t];
            if (c < colmin[j]) { colmin[j] = c; colarg[j] = i; }
        }
    }
    for (int j = n - 1; j >= 0; --j) {
        if (colarg[j] < 0) return -3; // column has no edge
        v[j] = colmin[j];
        int im = colarg[j];
        if (rowsol[im] == -1) {
            rowsol[im] = j;
            colsol[j] = im;
        }
    }

    std::vector<int> freer;
    for (int i = 0; i < n; ++i) if (rowsol[i] == -1) freer.push_back(i);

    // For Dijkstra we need fast lookup of row's candidate costs.
    // Build per-row map via scanning k entries (k small).

    auto augment = [&](int f) -> bool {
        std::fill(d.begin(), d.end(), INF);
        std::fill(in_tree.begin(), in_tree.end(), 0);
        {
            const int* id = idx + (int64_t)f * k;
            const double* cs = costs + (int64_t)f * k;
            for (int t = 0; t < k; ++t) {
                int j = id[t];
                double nd = cs[t] - v[j];
                if (nd < d[j]) { d[j] = nd; pred[j] = f; }
            }
        }
        int endcol = -1;
        while (true) {
            double h = INF;
            int jb = -1;
            for (int j = 0; j < n; ++j) if (!in_tree[j] && d[j] < h) { h = d[j]; jb = j; }
            if (jb < 0 || h >= INF/2) return false;
            in_tree[jb] = 1;
            int i0 = colsol[jb];
            if (i0 < 0) { endcol = jb; break; }
            // base reduced of (i0, jb)
            double cij = INF;
            {
                const int* id = idx + (int64_t)i0 * k;
                const double* cs = costs + (int64_t)i0 * k;
                for (int t = 0; t < k; ++t) if (id[t] == jb) { cij = cs[t]; break; }
            }
            double base = cij - v[jb];
            const int* id = idx + (int64_t)i0 * k;
            const double* cs = costs + (int64_t)i0 * k;
            for (int t = 0; t < k; ++t) {
                int j = id[t];
                if (in_tree[j]) continue;
                double nd = h + cs[t] - v[j] - base;
                if (nd < d[j]) { d[j] = nd; pred[j] = i0; }
            }
        }
        double dend = d[endcol];
        for (int j = 0; j < n; ++j) if (in_tree[j]) v[j] += d[j] - dend;
        int j = endcol;
        while (true) {
            int i0 = pred[j];
            colsol[j] = i0;
            int jn = rowsol[i0];
            rowsol[i0] = j;
            if (i0 == f) break;
            j = jn;
        }
        return true;
    };

    for (int i : freer) {
        if (!augment(i)) return -1;
    }
    return 0;
}
