/*
 * Jonker-Volgenant assignment (dense, square, minimize).
 * Implementation following the published algorithm:
 *   Jonker & Volgenant, "A shortest augmenting path algorithm for dense
 *   and sparse linear assignment problems", Computing 38, 1987.
 *   Crouse, IEEE TAES 2016 (rectangular extension notes).
 *
 * Optimized: column reduction, reduction transfer, augmenting row reduction,
 * then shortest augmenting paths with a binary heap.
 */
#include <cstdint>
#include <cmath>
#include <vector>
#include <algorithm>
#include <cstring>
#include <cstdio>

static constexpr double BIG = 1.0e18;

struct Heap {
    // min-heap of (key, col)
    std::vector<int> h;          // heap of columns
    std::vector<int> pos;        // col -> heap index or -1
    const double* key;
    int nheap;
    Heap(int n, const double* key): h(n), pos(n, -1), key(key), nheap(0) {}
    void clear() {
        for (int i = 0; i < nheap; ++i) pos[h[i]] = -1;
        nheap = 0;
    }
    void swap_at(int i, int j) {
        std::swap(h[i], h[j]);
        pos[h[i]] = i; pos[h[j]] = j;
    }
    void up(int i) {
        while (i > 0) {
            int p = (i - 1) >> 1;
            if (key[h[i]] < key[h[p]]) { swap_at(i, p); i = p; }
            else break;
        }
    }
    void down(int i) {
        while (true) {
            int l = i*2+1, r = l+1, b = i;
            if (l < nheap && key[h[l]] < key[h[b]]) b = l;
            if (r < nheap && key[h[r]] < key[h[b]]) b = r;
            if (b == i) break;
            swap_at(i, b); i = b;
        }
    }
    void push(int col) {
        int i = nheap++;
        h[i] = col; pos[col] = i;
        up(i);
    }
    void decrease(int col) {
        int i = pos[col];
        if (i < 0) push(col);
        else up(i);
    }
    int pop() {
        int c = h[0];
        pos[c] = -1;
        --nheap;
        if (nheap) {
            h[0] = h[nheap];
            pos[h[0]] = 0;
            down(0);
        }
        return c;
    }
    bool empty() const { return nheap == 0; }
};

extern "C" int jv_fast(const double* C, int n, int* rowsol) {
    std::vector<double> u(n, 0.0), v(n, 0.0), d(n);
    std::vector<int> colsol(n, -1), pred(n, -1);
    std::vector<uint8_t> scanned(n);
    std::fill(rowsol, rowsol + n, -1);

    // ========== COLUMN REDUCTION ==========
    for (int j = n - 1; j >= 0; --j) {
        const double* colptr_base = C; // C[i,j] = C[i*n+j]
        double m = C[j];
        int im = 0;
        for (int i = 1; i < n; ++i) {
            double c = C[(int64_t)i * n + j];
            if (c < m) { m = c; im = i; }
        }
        v[j] = m;
        if (rowsol[im] == -1) {
            rowsol[im] = j;
            colsol[j] = im;
        }
    }

    // ========== REDUCTION TRANSFER ==========
    std::vector<int> free_rows;
    free_rows.reserve(n);
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] != -1) {
            int j = rowsol[i];
            u[i] = C[(int64_t)i * n + j] - v[j];
        } else {
            free_rows.push_back(i);
        }
    }
    {
        std::vector<int> still;
        still.reserve(free_rows.size());
        for (int i : free_rows) {
            const double* row = C + (int64_t)i * n;
            double m1 = BIG, m2 = BIG;
            int j1 = -1;
            for (int j = 0; j < n; ++j) {
                double r = row[j] - v[j];
                if (r < m2) {
                    if (r >= m1) { m2 = r; }
                    else { m2 = m1; m1 = r; j1 = j; }
                }
            }
            u[i] = m1;
            if (m1 < m2) {
                int i0 = colsol[j1];
                if (i0 == -1 || u[i0] > m1) {  // transfer if better or free
                    // Jonker: transfer if v is from a row with higher u? 
                    // Standard: if column assigned and u[i0] - (C-v) ... 
                    if (i0 >= 0 && m2 - m1 <= u[i0] - (C[(int64_t)i0*n + j1] - v[j1]) + 1e-15) {
                        // previous owner equally good; don't transfer
                        still.push_back(i);
                        continue;
                    }
                    if (i0 >= 0) {
                        rowsol[i0] = -1;
                        still.push_back(i0);
                    }
                    rowsol[i] = j1;
                    colsol[j1] = i;
                    v[j1] = C[(int64_t)i * n + j1] - u[i]; // no, u[i]=m1=C-v so v unchanged
                    continue;
                }
            }
            still.push_back(i);
        }
        free_rows.swap(still);
    }

    // ========== AUGMENTING ROW REDUCTION ==========
    // Two passes over free rows: find min and second min reduced cost.
    // If unique min column is free or we can improve, assign; else if gap, raise v.
    for (int pass = 0; pass < 2; ++pass) {
        std::vector<int> still;
        still.reserve(free_rows.size());
        int k = 0;
        int nf = (int)free_rows.size();
        // process list, newly freed rows appended and processed in pass 1 only? both
        while (k < (int)free_rows.size()) {
            int i = free_rows[k++];
            if (rowsol[i] != -1) continue;
            const double* row = C + (int64_t)i * n;
            double m1 = BIG, m2 = BIG;
            int j1 = -1;
            for (int j = 0; j < n; ++j) {
                double r = row[j] - v[j];
                if (r < m2) {
                    if (r >= m1) m2 = r;
                    else { m2 = m1; m1 = r; j1 = j; }
                }
            }
            u[i] = m1;
            int i0 = colsol[j1];
            if (m1 < m2) {
                v[j1] -= (m2 - m1);  // augmenting row reduction: raise dual of column? 
                // reduced cost of j1 becomes equal to second: v[j1] += (m2-m1) would increase reduced of all... 
                // cost - v decreases if v increases. We want the min reduced to rise to m2,
                // so v[j1] decreases by (m2-m1)? r = c - v; to increase r by (m2-m1), decrease v.
                // Yes v[j1] -= (m2 - m1); then new reduced = m2.
                u[i] = m2; // after adjustment, reduced min equals m2? Wait:
                // after v[j1] -= (m2-m1), reduced of (i,j1) = m1 + (m2-m1) = m2. u = m2.
            }
            if (i0 >= 0) {
                // only steal if we improved dual (m1<m2) or column logic
                if (!(m1 < m2)) { still.push_back(i); continue; }
                rowsol[i0] = -1;
                free_rows.push_back(i0);
            }
            rowsol[i] = j1;
            colsol[j1] = i;
        }
        free_rows.swap(still);
        // remove assigned
        free_rows.clear();
        for (int i = 0; i < n; ++i) if (rowsol[i] == -1) free_rows.push_back(i);
    }

    // ========== SHORTEST AUGMENTING PATHS ==========
    Heap heap(n, d.data());
    int augmentations = 0;
    for (int f : free_rows) {
        if (rowsol[f] != -1) continue;
        const double* row = C + (int64_t)f * n;
        std::fill(scanned.begin(), scanned.end(), 0);
        heap.clear();
        for (int j = 0; j < n; ++j) {
            d[j] = row[j] - v[j];
            pred[j] = f;
        }
        // init heap with all columns — expensive. Instead linear first-min then heap for rest.
        // Use Dial-like: find initial min, then heap only updated nodes.
        double hmin = BIG;
        int jinit = -1;
        for (int j = 0; j < n; ++j) if (d[j] < hmin) { hmin = d[j]; jinit = j; }
        // We'll do a hybrid: scan all unscanned each time is O(n^2) per augment.
        // With heap of ALL columns push is O(n log n) per augment. For ~n/2 augments of n=600: 300*600*9 ~ 1.6e6 ops, fine.
        for (int j = 0; j < n; ++j) heap.push(j);

        int endcol = -1;
        while (!heap.empty()) {
            int jb = heap.pop();
            if (scanned[jb]) continue;
            scanned[jb] = 1;
            double h = d[jb];
            int i0 = colsol[jb];
            if (i0 < 0) { endcol = jb; break; }
            const double* r2 = C + (int64_t)i0 * n;
            double base = r2[jb] - v[jb];
            for (int j = 0; j < n; ++j) {
                if (scanned[j]) continue;
                double nd = h + r2[j] - v[j] - base;
                if (nd < d[j]) {
                    d[j] = nd;
                    pred[j] = i0;
                    heap.decrease(j);
                }
            }
        }
        if (endcol < 0) return -1;
        double dend = d[endcol];
        for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += d[j] - dend;
        u[f] = dend;
        int j = endcol;
        while (true) {
            int i0 = pred[j];
            colsol[j] = i0;
            int jn = rowsol[i0];
            rowsol[i0] = j;
            if (i0 == f) break;
            j = jn;
        }
        ++augmentations;
    }
    // fprintf(stderr, "aug %d free_start %d\n", augmentations, (int)free_rows.size());
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) return -2;
    return 0;
}
