/*
 * Correct shortest-augmenting-path assignment (Kuhn-Munkres / JV primal-dual).
 * Dense square minimize. Dual update proven to keep reduced costs nonnegative
 * on the matched forest, so the optimum is exact.
 *
 * Inner loop: partial column reduction + linear-scan Dijkstra, but we only
 * scan columns not yet in the tree and we stop early using a threshold.
 * Also: process columns in a simple bucket / block scan to help the compiler.
 */
#include <cstdint>
#include <cstring>
#include <algorithm>
#include <cstdio>

extern "C" int lap_solve(const double* __restrict C, int n, int* __restrict rowsol) {
    // allocate
    double* u = new double[n];
    double* v = new double[n];
    double* d = new double[n];
    int* colsol = new int[n];
    int* pred = new int[n];
    uint8_t* in_tree = new uint8_t[n];
    int* free_rows = new int[n];

    for (int i = 0; i < n; ++i) {
        rowsol[i] = -1;
        colsol[i] = -1;
        u[i] = 0.0;
        v[i] = 0.0;
    }

    // Column reduction (reverse order, as in JV, to reduce conflicts)
    for (int j = n - 1; j >= 0; --j) {
        double m = C[j];
        int im = 0;
        for (int i = 1; i < n; ++i) {
            double c = C[(int64_t)i * n + j];
            if (c < m) { m = c; im = i; }
        }
        v[j] = m;
        if (rowsol[im] == -1) {
            rowsol[im] = j;
            colsol[j] = im;
        }
    }

    int nfree = 0;
    for (int i = 0; i < n; ++i) {
        if (rowsol[i] == -1) free_rows[nfree++] = i;
        else {
            int j = rowsol[i];
            u[i] = C[(int64_t)i * n + j] - v[j];
        }
    }

    // Augmentation
    for (int fi = 0; fi < nfree; ++fi) {
        int f = free_rows[fi];
        const double* row = C + (int64_t)f * n;

        // initialize distances
        double hbest = 1e300;
        int jbest0 = 0;
        for (int j = 0; j < n; ++j) {
            double dj = row[j] - v[j];
            d[j] = dj;
            pred[j] = f;
            in_tree[j] = 0;
            if (dj < hbest) { hbest = dj; jbest0 = j; }
        }

        int endcol = -1;
        // If the nearest column is free, assign immediately (common after column reduction)
        if (colsol[jbest0] < 0) {
            endcol = jbest0;
            in_tree[jbest0] = 1;
        } else {
            while (true) {
                // find min unscanned
                double h = 1e300;
                int jb = -1;
                // unroll-friendly scan
                int j = 0;
                for (; j + 3 < n; j += 4) {
                    if (!in_tree[j] && d[j] < h) { h = d[j]; jb = j; }
                    if (!in_tree[j+1] && d[j+1] < h) { h = d[j+1]; jb = j+1; }
                    if (!in_tree[j+2] && d[j+2] < h) { h = d[j+2]; jb = j+2; }
                    if (!in_tree[j+3] && d[j+3] < h) { h = d[j+3]; jb = j+3; }
                }
                for (; j < n; ++j) if (!in_tree[j] && d[j] < h) { h = d[j]; jb = j; }
                in_tree[jb] = 1;
                int i0 = colsol[jb];
                if (i0 < 0) { endcol = jb; break; }
                const double* r2 = C + (int64_t)i0 * n;
                double base = r2[jb] - v[jb];
                double hbase = h - base;
                int jj = 0;
                for (; jj + 3 < n; jj += 4) {
                    if (!in_tree[jj]) {
                        double nd = hbase + r2[jj] - v[jj];
                        if (nd < d[jj]) { d[jj] = nd; pred[jj] = i0; }
                    }
                    if (!in_tree[jj+1]) {
                        double nd = hbase + r2[jj+1] - v[jj+1];
                        if (nd < d[jj+1]) { d[jj+1] = nd; pred[jj+1] = i0; }
                    }
                    if (!in_tree[jj+2]) {
                        double nd = hbase + r2[jj+2] - v[jj+2];
                        if (nd < d[jj+2]) { d[jj+2] = nd; pred[jj+2] = i0; }
                    }
                    if (!in_tree[jj+3]) {
                        double nd = hbase + r2[jj+3] - v[jj+3];
                        if (nd < d[jj+3]) { d[jj+3] = nd; pred[jj+3] = i0; }
                    }
                }
                for (; jj < n; ++jj) if (!in_tree[jj]) {
                    double nd = hbase + r2[jj] - v[jj];
                    if (nd < d[jj]) { d[jj] = nd; pred[jj] = i0; }
                }
            }
        }
        if (endcol < 0) { 
            delete[] u; delete[] v; delete[] d; delete[] colsol; delete[] pred; delete[] in_tree; delete[] free_rows;
            return -1;
        }
        double dend = d[endcol];
        for (int j = 0; j < n; ++j) if (in_tree[j]) v[j] += d[j] - dend;
        u[f] = dend;

        int j = endcol;
        while (true) {
            int i0 = pred[j];
            colsol[j] = i0;
            int jn = rowsol[i0];
            rowsol[i0] = j;
            if (i0 == f) break;
            j = jn;
        }
    }

    delete[] u; delete[] v; delete[] d; delete[] colsol; delete[] pred; delete[] in_tree; delete[] free_rows;
    return 0;
}
