/*
 * Epsilon-scaling auction algorithm for the dense assignment problem,
 * restricted to the k nearest neighbors of each row (plus dynamic edge insertion
 * is NOT done — caller must pass a k large enough to contain an optimal matching).
 *
 * We minimize cost. Auction is written on profits = -cost.
 *
 * Bertsekas epsilon-scaling auction, Jacobi (parallel) bidding variant
 * which is easier and still fast, plus Gauss-Seidel for the last phase.
 *
 * For exactness: final epsilon must be smaller than half the minimum
 * reduced-cost gap. With float distances this can be tiny, so we finish
 * with a shortest-augmenting-path cleanup on the sparse graph using the
 * auction prices as warm start — that guarantees optimality over the sparse
 * graph (and thus globally if the optimum edges are included).
 */
#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <vector>
#include <cstdio>

// Sparse SAP given kNN lists. Warm-started duals v (column prices).
// Returns 0 and fills rowsol if an optimal assignment over the sparse graph exists.
extern "C" int sparse_sap(
    const int* __restrict idx,      // n*k int32
    const double* __restrict costs, // n*k float64
    int n, int k,
    double* __restrict v_init,      // n, may be null
    int* __restrict rowsol
) {
    double* v = new double[n];
    double* d = new double[n];
    int* colsol = new int[n];
    int* pred = new int[n];
    uint8_t* in_tree = new uint8_t[n];
    int* freer = new int[n];

    for (int j = 0; j < n; ++j) {
        v[j] = v_init ? v_init[j] : 0.0;
        colsol[j] = -1;
    }
    for (int i = 0; i < n; ++i) rowsol[i] = -1;

    // Column reduction over sparse edges, using current v (reduced costs)
    // Find for each column the min reduced incoming edge, assign if row free.
    // Do it by scanning rows.
    double* colmin = new double[n];
    int* colarg = new int[n];
    for (int j = 0; j < n; ++j) { colmin[j] = 1e300; colarg[j] = -1; }
    for (int i = 0; i < n; ++i) {
        const int* id = idx + (int64_t)i * k;
        const double* cs = costs + (int64_t)i * k;
        for (int t = 0; t < k; ++t) {
            int j = id[t];
            double r = cs[t] - v[j];
            if (r < colmin[j]) { colmin[j] = r; colarg[j] = i; }
        }
    }
    for (int j = n - 1; j >= 0; --j) {
        int im = colarg[j];
        if (im < 0) continue;
        if (rowsol[im] == -1) {
            rowsol[im] = j;
            colsol[j] = im;
        }
    }

    int nfree = 0;
    for (int i = 0; i < n; ++i) if (rowsol[i] == -1) freer[nfree++] = i;

    for (int fi = 0; fi < nfree; ++fi) {
        int f = freer[fi];
        // init d = INF, then set candidates
        for (int j = 0; j < n; ++j) { d[j] = 1e300; in_tree[j] = 0; pred[j] = -1; }
        {
            const int* id = idx + (int64_t)f * k;
            const double* cs = costs + (int64_t)f * k;
            for (int t = 0; t < k; ++t) {
                int j = id[t];
                double nd = cs[t] - v[j];
                if (nd < d[j]) { d[j] = nd; pred[j] = f; }
            }
        }
        int endcol = -1;
        // Dijkstra linear scan over finite d only — still O(n) per step but few steps if k small
        // Track a list of columns that have finite d to scan faster.
        int* finite = new int[n];
        uint8_t* is_fin = new uint8_t[n];
        int nf = 0;
        for (int j = 0; j < n; ++j) if (d[j] < 1e299) { finite[nf++] = j; is_fin[j] = 1; }
        else is_fin[j] = 0;

        while (true) {
            double h = 1e300;
            int jb = -1, jbpos = -1;
            for (int p = 0; p < nf; ++p) {
                int j = finite[p];
                if (!in_tree[j] && d[j] < h) { h = d[j]; jb = j; jbpos = p; }
            }
            if (jb < 0) { delete[] finite; delete[] is_fin;
                delete[] v; delete[] d; delete[] colsol; delete[] pred; delete[] in_tree; delete[] freer;
                delete[] colmin; delete[] colarg;
                return -1; }
            in_tree[jb] = 1;
            int i0 = colsol[jb];
            if (i0 < 0) { endcol = jb; delete[] finite; delete[] is_fin; break; }
            // find cost of (i0, jb)
            double cij = 0;
            {
                const int* id = idx + (int64_t)i0 * k;
                const double* cs = costs + (int64_t)i0 * k;
                cij = 1e300;
                for (int t = 0; t < k; ++t) if (id[t] == jb) { cij = cs[t]; break; }
            }
            double base = cij - v[jb];
            double hbase = h - base;
            const int* id = idx + (int64_t)i0 * k;
            const double* cs = costs + (int64_t)i0 * k;
            for (int t = 0; t < k; ++t) {
                int j = id[t];
                if (in_tree[j]) continue;
                double nd = hbase + cs[t] - v[j];
                if (nd < d[j]) {
                    d[j] = nd;
                    pred[j] = i0;
                    if (!is_fin[j]) { is_fin[j] = 1; finite[nf++] = j; }
                }
            }
        }
        double dend = d[endcol];
        for (int j = 0; j < n; ++j) if (in_tree[j]) v[j] += d[j] - dend;
        int j = endcol;
        while (true) {
            int i0 = pred[j];
            colsol[j] = i0;
            int jn = rowsol[i0];
            rowsol[i0] = j;
            if (i0 == f) break;
            j = jn;
        }
    }

    if (v_init) for (int j = 0; j < n; ++j) v_init[j] = v[j];
    delete[] v; delete[] d; delete[] colsol; delete[] pred; delete[] in_tree; delete[] freer;
    delete[] colmin; delete[] colarg;
    return 0;
}

/*
 * Gauss-Seidel auction on sparse kNN graph.
 * prices: column prices (on cost scale, we bid using value = -cost - price? )
 * We store price such that "profit" of edge = -cost - price, and price increases.
 * Returns number of iterations. Fills rowsol. Not guaranteed exact.
 */
extern "C" int auction_sparse(
    const int* idx, const double* costs,
    int n, int k,
    double eps_final,
    int* rowsol,
    double* prices_out
) {
    double* price = new double[n];
    int* owner = new int[n];
    for (int j = 0; j < n; ++j) { price[j] = 0.0; owner[j] = -1; }
    for (int i = 0; i < n; ++i) rowsol[i] = -1;

    // epsilon scaling
    // estimate initial eps from a sample of cost ranges
    double cmax = -1e300, cmin = 1e300;
    int sample = n < 32 ? n : 32;
    for (int i = 0; i < sample; ++i) {
        const double* cs = costs + (int64_t)i * k;
        for (int t = 0; t < k; ++t) {
            if (cs[t] > cmax) cmax = cs[t];
            if (cs[t] < cmin) cmin = cs[t];
        }
    }
    double eps = (cmax - cmin) / 4.0;
    if (eps < eps_final) eps = eps_final;

    int total_bids = 0;
    int* unassigned = new int[n];
    int nu;

    while (true) {
        // reset assignment each phase but keep prices (epsilon scaling)
        for (int j = 0; j < n; ++j) owner[j] = -1;
        for (int i = 0; i < n; ++i) rowsol[i] = -1;
        nu = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        // actually a stack
        int top = n; // unassigned[0..top)
        // use stack from the right
        int iter_guard = n * 40 + 1000;
        while (top > 0) {
            if (--iter_guard < 0) {
                // failed to converge this phase
                break;
            }
            int i = unassigned[--top];
            const int* id = idx + (int64_t)i * k;
            const double* cs = costs + (int64_t)i * k;
            // find best and second best profit = -cost - price
            double best = -1e300, second = -1e300;
            int jbest = id[0];
            for (int t = 0; t < k; ++t) {
                int j = id[t];
                double val = -cs[t] - price[j];
                if (val > best) { second = best; best = val; jbest = j; }
                else if (val > second) { second = val; }
            }
            if (second < -1e299) second = best - 1.0; // only one edge
            double bid = best - second + eps;
            price[jbest] += bid;
            int prev = owner[jbest];
            if (prev != -1) {
                rowsol[prev] = -1;
                unassigned[top++] = prev;
            }
            owner[jbest] = i;
            rowsol[i] = jbest;
            ++total_bids;
        }
        if (eps <= eps_final * 1.0001) break;
        eps *= 0.2;
        if (eps < eps_final) eps = eps_final;
    }

    if (prices_out) for (int j = 0; j < n; ++j) prices_out[j] = price[j];
    delete[] price; delete[] owner; delete[] unassigned;
    return total_bids;
}
