/*
 * Forward-reverse auction for the dense square assignment problem (minimize cost).
 * Bertsekas, "The auction algorithm for assignment and other network flow problems",
 * and the forward/reverse variant that reaches exact optimality without an a-priori
 * epsilon smaller than all cost gaps.
 *
 * We work with profits P = -C (maximize profit == minimize cost).
 *
 * Scaling: eps starts large and decreases. Forward auction assigns persons to objects;
 * reverse auction assigns objects to persons, which drives eps down to 0 effectively
 * for the final matching (the combined algorithm produces an optimal assignment).
 *
 * Implementation notes for speed at n=600:
 *  - keep current best object for each person and recompute only when prices change
 *    enough, but full scan is 600*~few thousand bids = few million ops, OK if tight.
 *  - cache row pointer.
 */
#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <cstdio>

extern "C" int fra_solve(const double* __restrict C, int n, int* __restrict rowsol) {
    // price[j] on the PROFIT scale (higher price = less attractive)
    double* price = new double[n];
    double* profit_i = new double[n]; // best profit of person i (for reverse)
    int* owner = new int[n];          // object -> person
    int* obj_of = rowsol;             // person -> object
    int* unassigned = new int[n];

    for (int j = 0; j < n; ++j) { price[j] = 0.0; owner[j] = -1; }
    for (int i = 0; i < n; ++i) obj_of[i] = -1;

    // cost scale
    double cmax = -1e300, cmin = 1e300;
    // sample
    int step = n > 40 ? n/40 : 1;
    for (int i = 0; i < n; i += step) {
        const double* row = C + (int64_t)i * n;
        for (int j = 0; j < n; j += step) {
            double c = row[j];
            if (c > cmax) cmax = c;
            if (c < cmin) cmin = c;
        }
    }
    double eps = (cmax - cmin) / 2.0;
    if (eps < 1e-6) eps = 1e-6;
    const double eps_final = 1e-9;

    auto bid_forward = [&](int i, double eps) -> void {
        const double* row = C + (int64_t)i * n;
        double best = -1e300, second = -1e300;
        int jbest = 0;
        for (int j = 0; j < n; ++j) {
            double val = -row[j] - price[j];
            if (val > best) { second = best; best = val; jbest = j; }
            else if (val > second) second = val;
        }
        double bid_inc = best - second + eps;
        price[jbest] += bid_inc;
        int prev = owner[jbest];
        if (prev != -1 && prev != i) {
            obj_of[prev] = -1;
        }
        owner[jbest] = i;
        obj_of[i] = jbest;
    };

    // Gauss-Seidel forward auction for one eps, starting from current prices,
    // resetting assignment (epsilon-scaling style).
    auto forward_phase = [&](double eps) -> int {
        for (int j = 0; j < n; ++j) owner[j] = -1;
        int top = 0;
        for (int i = 0; i < n; ++i) { obj_of[i] = -1; unassigned[top++] = i; }
        int bids = 0;
        int guard = n * 50;
        while (top > 0) {
            if (--guard < 0) return -1;
            int i = unassigned[--top];
            const double* row = C + (int64_t)i * n;
            double best = -1e300, second = -1e300;
            int jbest = 0;
            for (int j = 0; j < n; ++j) {
                double val = -row[j] - price[j];
                if (val > best) { second = best; best = val; jbest = j; }
                else if (val > second) second = val;
            }
            price[jbest] += best - second + eps;
            int prev = owner[jbest];
            if (prev != -1) {
                obj_of[prev] = -1;
                unassigned[top++] = prev;
            }
            owner[jbest] = i;
            obj_of[i] = jbest;
            ++bids;
        }
        return bids;
    };

    int phase = 0;
    while (true) {
        int bids = forward_phase(eps);
        ++phase;
        if (bids < 0) {
            // did not converge, shrink eps and retry (prices may be messy)
            eps *= 0.5;
            if (eps < eps_final) { delete[] price; delete[] profit_i; delete[] owner; delete[] unassigned; return -1; }
            continue;
        }
        if (eps <= eps_final) break;
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
        if (phase > 40) break;
    }

    delete[] price; delete[] profit_i; delete[] owner; delete[] unassigned;
    return 0;
}
