/*
 * Epsilon-scaling forward auction, minimize cost.
 * Bidding scans a kNN candidate list first. If the second-best among candidates
 * might not be global (i.e. we need the true second best to set the bid), we
 * do a full scan only when the candidate-restricted bid would be large — 
 * actually for correctness of the final assignment at small eps, each bid must
 * use the true best and second-best over ALL columns.
 *
 * Speed trick: maintain for each person the best object and its value, and a
 * "price threshold". Prices only increase, so a person's values only decrease.
 * We can:
 *   - keep the current best column and value
 *   - rescan fully only when the best column's price has increased (value dropped)
 *     or when we are bidding.
 * A full scan per bid is the naive cost. Number of bids at n=600 was ~20k for
 * sparse and likely similar for dense with good scaling. 20k * 600 = 12M ops,
 * should be ~5-15ms if the loop is tight. The previous 20ms suggests ~that.
 * Let's tighten the inner loop and also use partial scans:
 *   Store price_stamp. For each person cache (jbest, best_val_at_price0?).
 *
 * Better idea: SIMD-friendly loop + restrict + prefetch.
 * Also start from a kNN-auction warm start (fast, ~3ms) then only a few dense
 * refinement bids are needed? If kNN auction already optimal, zero dense bids.
 * If not, run dense auction from those prices — but dense auction resets assignment.
 * We can continue: any person who prefers an object outside their kNN will bid
 * for it during dense refinement. So:
 *   1. kNN auction to small eps (fast, good prices and assignment)
 *   2. Check eps-complementary slack for each person over ALL columns.
 *      If everyone is happy within eps, assignment is eps-optimal.
 *   3. Otherwise run dense GS auction from current prices & assignment
 *      (do NOT reset), with small eps, only unassigned + unhappy persons bid.
 *
 * For EXACT match with network simplex we need the same basic optimal solution,
 * not just any optimal. Auction returns an optimal assignment but which one
 * if there are ties?
 * With generic Euclidean costs, the optimum assignment is unique with probability 1.
 * So any optimal assignment should match. Verify.
 */
#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <cstdio>

static inline void best_two(const double* row, const double* price, int n,
                            double& best, double& second, int& jbest) {
    best = -1e300; second = -1e300; jbest = 0;
    int j = 0;
    for (; j + 1 < n; j += 2) {
        double v0 = -row[j] - price[j];
        double v1 = -row[j+1] - price[j+1];
        // insert v0
        if (v0 > best) { second = best; best = v0; jbest = j; }
        else if (v0 > second) second = v0;
        if (v1 > best) { second = best; best = v1; jbest = j+1; }
        else if (v1 > second) second = v1;
    }
    if (j < n) {
        double v0 = -row[j] - price[j];
        if (v0 > best) { second = best; best = v0; jbest = j; }
        else if (v0 > second) second = v0;
    }
}

extern "C" int auction_dense(const double* __restrict C, int n, int* __restrict rowsol) {
    double* price = new double[n];
    int* owner = new int[n];
    int* stack = new int[n];
    for (int j = 0; j < n; ++j) { price[j] = 0.0; owner[j] = -1; }
    for (int i = 0; i < n; ++i) rowsol[i] = -1;

    double cmax = -1e300, cmin = 1e300;
    int step = std::max(1, n/50);
    for (int i = 0; i < n; i += step) {
        const double* row = C + (int64_t)i * n;
        for (int j = 0; j < n; j += step) {
            double c = row[j];
            if (c > cmax) cmax = c;
            if (c < cmin) cmin = c;
        }
    }
    double eps = (cmax - cmin) / 4.0;
    const double eps_final = 1e-10;

    int phase_guard = 0;
    while (eps >= eps_final * 0.5 && phase_guard < 30) {
        ++phase_guard;
        for (int j = 0; j < n; ++j) owner[j] = -1;
        int top = 0;
        for (int i = 0; i < n; ++i) { rowsol[i] = -1; stack[top++] = i; }
        int guard = n * 80;
        while (top > 0) {
            if (--guard < 0) break;
            int i = stack[--top];
            const double* row = C + (int64_t)i * n;
            double best, second; int jbest;
            best_two(row, price, n, best, second, jbest);
            price[jbest] += best - second + eps;
            int prev = owner[jbest];
            if (prev != -1) {
                rowsol[prev] = -1;
                stack[top++] = prev;
            }
            owner[jbest] = i;
            rowsol[i] = jbest;
        }
        if (eps <= eps_final) break;
        eps *= 0.2;
        if (eps < eps_final) eps = eps_final;
    }
    delete[] price; delete[] owner; delete[] stack;
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) return -1;
    return 0;
}
