/*
 * Hybrid assignment:
 *  1) Build nothing here — caller passes full cost matrix.
 *  2) We run a kNN auction internally by partial-sorting each row (quickselect)
 *     then epsilon-scaling auction on those edges.
 *  3) Then a dense refinement: persons bid over all columns, but we keep prices
 *     and only re-bid unhappy persons. Prices from kNN auction are on the profit
 *     scale and remain valid (prices only increase).
 *  4) Final eps small enough for exactness on generic costs.
 */
#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <vector>
#include <cstdio>
#include <cstdlib>

// quickselect smallest k indices by cost (in-place on idx array of size n)
static void select_k(const double* row, int* idx, int n, int k) {
    for (int i = 0; i < n; ++i) idx[i] = i;
    // nth_element
    std::nth_element(idx, idx + k, idx + n, [&](int a, int b){ return row[a] < row[b]; });
}

extern "C" int hybrid_solve(const double* __restrict C, int n, int k, int* __restrict rowsol) {
    double* price = new double[n];
    int* owner = new int[n];
    int* stack = new int[n];
    std::memset(price, 0, sizeof(double)*n);

    // kNN lists
    int* knn = new int[(int64_t)n * k];
    double* knnc = new double[(int64_t)n * k];
    int* tmp = new int[n];
    for (int i = 0; i < n; ++i) {
        const double* row = C + (int64_t)i * n;
        select_k(row, tmp, n, k);
        int* id = knn + (int64_t)i * k;
        double* cs = knnc + (int64_t)i * k;
        for (int t = 0; t < k; ++t) {
            id[t] = tmp[t];
            cs[t] = row[tmp[t]];
        }
    }

    auto phase_sparse = [&](double eps) -> int {
        for (int j = 0; j < n; ++j) owner[j] = -1;
        int top = 0;
        for (int i = 0; i < n; ++i) { rowsol[i] = -1; stack[top++] = i; }
        int guard = n * 60;
        int bids = 0;
        while (top > 0) {
            if (--guard < 0) return -1;
            int i = stack[--top];
            const int* id = knn + (int64_t)i * k;
            const double* cs = knnc + (int64_t)i * k;
            double best = -1e300, second = -1e300;
            int jbest = id[0];
            for (int t = 0; t < k; ++t) {
                double val = -cs[t] - price[id[t]];
                if (val > best) { second = best; best = val; jbest = id[t]; }
                else if (val > second) second = val;
            }
            price[jbest] += best - second + eps;
            int prev = owner[jbest];
            if (prev != -1) { rowsol[prev] = -1; stack[top++] = prev; }
            owner[jbest] = i;
            rowsol[i] = jbest;
            ++bids;
        }
        return bids;
    };

    double cmax = -1e300, cmin = 1e300;
    for (int i = 0; i < std::min(n, 40); ++i) {
        const double* cs = knnc + (int64_t)i * k;
        for (int t = 0; t < k; ++t) {
            if (cs[t] > cmax) cmax = cs[t];
            if (cs[t] < cmin) cmin = cs[t];
        }
    }
    double eps = (cmax - cmin) / 4.0;
    const double eps_switch = 1e-4;  // switch to dense refinement below this
    const double eps_final = 1e-10;

    int phases = 0;
    while (eps > eps_switch && phases < 20) {
        int b = phase_sparse(eps);
        if (b < 0) break;
        eps *= 0.2;
        ++phases;
    }

    // Dense refinement phases. Keep prices. Reset assignment each phase
    // (standard eps scaling) but scan all columns.
    auto best_two = [&](const double* row, double& best, double& second, int& jbest) {
        best = -1e300; second = -1e300; jbest = 0;
        for (int j = 0; j < n; ++j) {
            double val = -row[j] - price[j];
            if (val > best) { second = best; best = val; jbest = j; }
            else if (val > second) second = val;
        }
    };

    int dense_bids = 0;
    while (phases < 30) {
        for (int j = 0; j < n; ++j) owner[j] = -1;
        int top = 0;
        for (int i = 0; i < n; ++i) { rowsol[i] = -1; stack[top++] = i; }
        int guard = n * 80;
        while (top > 0) {
            if (--guard < 0) break;
            int i = stack[--top];
            const double* row = C + (int64_t)i * n;
            double best, second; int jbest;
            best_two(row, best, second, jbest);
            price[jbest] += best - second + eps;
            int prev = owner[jbest];
            if (prev != -1) { rowsol[prev] = -1; stack[top++] = prev; }
            owner[jbest] = i;
            rowsol[i] = jbest;
            ++dense_bids;
        }
        if (eps <= eps_final) break;
        eps *= 0.2;
        if (eps < eps_final) eps = eps_final;
        ++phases;
    }

    delete[] price; delete[] owner; delete[] stack; delete[] knn; delete[] knnc; delete[] tmp;
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) return -1;
    return dense_bids;
}
