#include <cstdint>
#include <cstdio>
#include <chrono>
#include <cmath>
#include <algorithm>
#include <immintrin.h>
#include <cstdlib>

// Time a best-two scan over n x n matrix, repeated `reps` times (like bids).
static void best_two_scalar(const double* row, const double* price, int n,
                            double& best, double& second, int& jbest) {
    best = -1e300; second = -1e300; jbest = 0;
    for (int j = 0; j < n; ++j) {
        double val = -row[j] - price[j];
        if (val > best) { second = best; best = val; jbest = j; }
        else if (val > second) second = val;
    }
}

static void best_two_avx(const double* row, const double* price, int n,
                         double& best, double& second, int& jbest) {
    // process 4 doubles
    best = -1e300; second = -1e300; jbest = 0;
    int j = 0;
    for (; j + 3 < n; j += 4) {
        __m256d r = _mm256_loadu_pd(row + j);
        __m256d p = _mm256_loadu_pd(price + j);
        __m256d v = _mm256_sub_pd(_mm256_sub_pd(_mm256_setzero_pd(), r), p); // -r -p
        alignas(32) double vs[4];
        _mm256_store_pd(vs, v);
        #pragma unroll
        for (int t = 0; t < 4; ++t) {
            double val = vs[t];
            if (val > best) { second = best; best = val; jbest = j+t; }
            else if (val > second) second = val;
        }
    }
    for (; j < n; ++j) {
        double val = -row[j] - price[j];
        if (val > best) { second = best; best = val; jbest = j; }
        else if (val > second) second = val;
    }
}

int main() {
    int n = 600;
    int reps = 20000;
    double* C = (double*)aligned_alloc(32, sizeof(double)*n*n);
    double* price = (double*)aligned_alloc(32, sizeof(double)*n);
    for (int i = 0; i < n*n; ++i) C[i] = (i * 17 % 1000) / 1000.0;
    for (int j = 0; j < n; ++j) price[j] = (j % 50) / 1000.0;

    double best, second; int jbest;
    auto t0 = std::chrono::high_resolution_clock::now();
    double acc = 0;
    for (int r = 0; r < reps; ++r) {
        int i = r % n;
        best_two_scalar(C + (int64_t)i*n, price, n, best, second, jbest);
        acc += best;
    }
    auto t1 = std::chrono::high_resolution_clock::now();
    double ms = std::chrono::duration<double, std::milli>(t1-t0).count();
    printf("scalar %d scans: %.2f ms  (%.3f us/scan) acc=%g\n", reps, ms, ms*1000/reps, acc);

    t0 = std::chrono::high_resolution_clock::now();
    acc = 0;
    for (int r = 0; r < reps; ++r) {
        int i = r % n;
        best_two_avx(C + (int64_t)i*n, price, n, best, second, jbest);
        acc += best;
    }
    t1 = std::chrono::high_resolution_clock::now();
    ms = std::chrono::duration<double, std::milli>(t1-t0).count();
    printf("avx    %d scans: %.2f ms  (%.3f us/scan) acc=%g\n", reps, ms, ms*1000/reps, acc);

    // bandwidth: read whole matrix once
    t0 = std::chrono::high_resolution_clock::now();
    acc = 0;
    for (int i = 0; i < n; ++i) {
        const double* row = C + (int64_t)i*n;
        __m256d s = _mm256_setzero_pd();
        for (int j = 0; j < n; j += 4) s = _mm256_add_pd(s, _mm256_load_pd(row+j));
        alignas(32) double vs[4]; _mm256_store_pd(vs, s);
        acc += vs[0]+vs[1]+vs[2]+vs[3];
    }
    t1 = std::chrono::high_resolution_clock::now();
    ms = std::chrono::duration<double, std::milli>(t1-t0).count();
    printf("read matrix once: %.3f ms acc=%g\n", ms, acc);
    return 0;
}
