{"command":"cat > build/jv.cpp << 'EOF'
/*
 * Jonker-Volgenant algorithm for dense square LAP (minimize).
 * Port of the classical implementation (Jonker & Volgenant 1987),
 * double precision adaptation of the integer version widely circulated
 * as lapjv (public-domain educational ports, e.g. the algorithm description
 * in Crouse 2016).
 *
 * Column reduction + reduction transfer + augmenting row reduction
 * drastically cut the number of shortest augmenting paths.
 */
#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <cstdio>
#include <cstdlib>

static constexpr double BIG = 1e18;
static constexpr double EPS = 1e-12;

extern "C" int jv(const double* __restrict cost, int n, int* __restrict x, int* aug_out) {
    // x[i] = column assigned to row i
    // y[j] = row assigned to column j
    int* y = new int[n];
    double* u = new double[n];
    double* v = new double[n];
    double* d = new double[n];
    int* pred = new int[n];
    int* free_rows = new int[n];
    uint8_t* unique = new uint8_t[n];
    int* col = new int[n]; // scan list

    for (int i = 0; i < n; ++i) { x[i] = -1; y[i] = -1; u[i] = 0; v[i] = 0; }

    // ---- COLUMN REDUCTION ----
    for (int j = n - 1; j >= 0; --j) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double c = cost[(int64_t)i * n + j];
            if (c < minv) { minv = c; imin = i; }
        }
        v[j] = minv;
        if (x[imin] == -1) { x[imin] = j; y[j] = imin; }
    }

    // ---- REDUCTION TRANSFER ----
    int nfree = 0;
    for (int i = 0; i < n; ++i) {
        if (x[i] != -1) {
            int j = x[i];
            u[i] = cost[(int64_t)i * n + j] - v[j];
        } else {
            free_rows[nfree++] = i;
        }
    }
    int nfree_new = 0;
    int* free2 = new int[n];
    for (int fi = 0; fi < nfree; ++fi) {
        int i = free_rows[fi];
        const double* row = cost + (int64_t)i * n;
        double minv = BIG, second = BIG;
        int jmin = -1;
        for (int j = 0; j < n; ++j) {
            double red = row[j] - v[j];
            if (red < second) {
                if (red >= minv) second = red;
                else { second = minv; minv = red; jmin = j; }
            }
        }
        u[i] = minv;
        int j = jmin;
        if (second - minv > EPS) {
            // unique minimum: try to transfer
            int i0 = y[j];
            if (i0 < 0 || u[i0] > minv + EPS) {
                if (i0 >= 0) {
                    x[i0] = -1;
                    free2[nfree_new++] = i0;
                }
                x[i] = j; y[j] = i;
                v[j] = row[j] - minv; // unchanged essentially if i0<0; if transfer, lower? 
                // Standard JV sets v[j] = cost[i][j] - minv which equals old v if minv = cost-v.
                // minv = row[j]-v[j] so row[j]-minv = v[j]. No change. OK.
                continue;
            }
        }
        free2[nfree_new++] = i;
    }
    // copy back unassigned that we didn't re-free incorrectly
    // free2 contains rows still free. But transferred rows' previous owners were added,
    // and successfully assigned rows were not. Good.
    for (int t = 0; t < nfree_new; ++t) free_rows[t] = free2[t];
    nfree = nfree_new;

    // Remove any that got assigned (shouldn't happen) 
    {
        int w = 0;
        for (int t = 0; t < nfree; ++t) if (x[free_rows[t]] < 0) free_rows[w++] = free_rows[t];
        nfree = w;
    }

    // ---- AUGMENTING ROW REDUCTION ----
    int nscan = 0;
    for (int pass = 0; pass < 2; ++pass) {
        int head = 0;
        while (head < nfree) {
            int i = free_rows[head++];
            if (x[i] >= 0) continue;
            const double* row = cost + (int64_t)i * n;
            double minv = BIG, second = BIG;
            int jmin = -1;
            for (int j = 0; j < n; ++j) {
                double red = row[j] - v[j];
                if (red < second) {
                    if (red >= minv) second = red;
                    else { second = minv; minv = red; jmin = j; }
                }
            }
            int j = jmin;
            int i0 = y[j];
            if (minv < second - EPS) {
                v[j] -= (second - minv);
                // now reduced cost of (i,j) equals second
            }
            if (i0 >= 0) {
                if (!(minv < second - EPS)) {
                    // cannot profitably steal
                    free2[nscan++] = i; // defer; we'll rebuild
                    continue;
                }
                x[i0] = -1;
                free_rows[nfree++] = i0; // process later in this pass
            }
            x[i] = j; y[j] = i;
            u[i] = (minv < second - EPS) ? second : minv;
        }
        // rebuild free list from deferred + still unassigned
        // Actually deferred were stored in free2 only on the no-steal path, and new frees appended to free_rows.
        // This bookkeeping is getting messy. Rebuild from x.
        nfree = 0;
        for (int i = 0; i < n; ++i) if (x[i] < 0) free_rows[nfree++] = i;
        nscan = 0;
    }

    int augments = 0;
    // ---- SHORTEST AUGMENTING PATHS ----
    for (int fi = 0; fi < nfree; ++fi) {
        int f = free_rows[fi];
        if (x[f] >= 0) continue;
        const double* row = cost + (int64_t)f * n;

        uint8_t* in_tree = unique; // reuse
        std::memset(in_tree, 0, n);
        double hmin = BIG;
        for (int j = 0; j < n; ++j) {
            d[j] = row[j] - v[j];
            pred[j] = f;
            if (d[j] < hmin) hmin = d[j];
        }
        int endcol = -1;
        while (true) {
            double h = BIG; int jb = -1;
            for (int j = 0; j < n; ++j) if (!in_tree[j] && d[j] < h) { h = d[j]; jb = j; }
            in_tree[jb] = 1;
            int i0 = y[jb];
            if (i0 < 0) { endcol = jb; break; }
            const double* r2 = cost + (int64_t)i0 * n;
            double base = r2[jb] - v[jb];
            double hb = h - base;
            for (int j = 0; j < n; ++j) if (!in_tree[j]) {
                double nd = hb + r2[j] - v[j];
                if (nd < d[j]) { d[j] = nd; pred[j] = i0; }
            }
        }
        double dend = d[endcol];
        for (int j = 0; j < n; ++j) if (in_tree[j]) v[j] += d[j] - dend;

        int j = endcol;
        while (true) {
            int i0 = pred[j];
            y[j] = i0;
            int jn = x[i0];
            x[i0] = j;
            if (i0 == f) break;
            j = jn;
        }
        ++augments;
    }

    if (aug_out) *aug_out = augments;
    int rc = 0;
    for (int i = 0; i < n; ++i) if (x[i] < 0) rc = -1;

    delete[] y; delete[] u; delete[] v; delete[] d; delete[] pred;
    delete[] free_rows; delete[] unique; delete[] col; delete[] free2;
    return rc;
}
