#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <cstdio>

struct Cnt { int bids; int phases; int scans; };

static void best_two(const double* row, const double* price, int n,
                     double& best, double& second, int& jbest) {
    best = -1e300; second = -1e300; jbest = 0;
    for (int j = 0; j < n; ++j) {
        double val = -row[j] - price[j];
        if (val > best) { second = best; best = val; jbest = j; }
        else if (val > second) second = val;
    }
}

// mode 0: reset assignment each phase (classic)
// mode 1: keep assignment, only unassigned bid (prices persist). May stall if eps-CS violated for assigned.
extern "C" int auction_count(const double* C, int n, int mode, int* rowsol, int* stats) {
    double* price = new double[n]();
    int* owner = new int[n];
    int* stack = new int[n];
    for (int j = 0; j < n; ++j) owner[j] = -1;

    double cmax = -1e300, cmin = 1e300;
    int step = std::max(1, n/50);
    for (int i = 0; i < n; i += step) {
        const double* row = C + (int64_t)i * n;
        for (int j = 0; j < n; j += step) {
            double c = row[j];
            if (c > cmax) cmax = c;
            if (c < cmin) cmin = c;
        }
    }
    double eps = (cmax - cmin) / 4.0;
    const double eps_final = 1e-10;
    int bids = 0, phases = 0, scans = 0;

    if (mode == 0) {
        while (phases < 30) {
            ++phases;
            for (int j = 0; j < n; ++j) owner[j] = -1;
            int top = 0;
            for (int i = 0; i < n; ++i) { rowsol[i] = -1; stack[top++] = i; }
            int guard = n * 100;
            while (top > 0 && guard-- > 0) {
                int i = stack[--top];
                double best, second; int jbest;
                best_two(C + (int64_t)i * n, price, n, best, second, jbest);
                ++scans;
                price[jbest] += best - second + eps;
                int prev = owner[jbest];
                if (prev != -1) { rowsol[prev] = -1; stack[top++] = prev; }
                owner[jbest] = i;
                rowsol[i] = jbest;
                ++bids;
            }
            if (eps <= eps_final) break;
            eps *= 0.2;
            if (eps < eps_final) eps = eps_final;
        }
    } else {
        // single decreasing eps, keep assignment. When eps decreases, recheck all persons:
        // a person bids if their current object is not within eps of the best.
        for (int i = 0; i < n; ++i) rowsol[i] = -1;
        for (int j = 0; j < n; ++j) owner[j] = -1;
        while (phases < 30) {
            ++phases;
            int top = 0;
            for (int i = 0; i < n; ++i) stack[top++] = i; // all reconsider
            int guard = n * 100;
            while (top > 0 && guard-- > 0) {
                int i = stack[--top];
                double best, second; int jbest;
                best_two(C + (int64_t)i * n, price, n, best, second, jbest);
                ++scans;
                int cur = rowsol[i];
                if (cur == jbest) {
                    // happy enough? bid only if we want to push price to eps-CS
                    // If already assigned to best, the complementary slack is best-second.
                    // Raise price so that best becomes equal to second+? 
                    // Standard GS auction always bids even if assigned to best, increasing price
                    // by best-second+eps, which unassigns self and reassigns — infinite loop if not careful.
                    // Only bid if not assigned to jbest.
                    continue;
                }
                // if assigned elsewhere, unassign self first
                if (cur >= 0) { owner[cur] = -1; rowsol[i] = -1; }
                price[jbest] += best - second + eps;
                int prev = owner[jbest];
                if (prev != -1) { rowsol[prev] = -1; stack[top++] = prev; }
                owner[jbest] = i;
                rowsol[i] = jbest;
                ++bids;
            }
            if (eps <= eps_final) break;
            eps *= 0.2;
            if (eps < eps_final) eps = eps_final;
        }
    }
    stats[0] = bids; stats[1] = phases; stats[2] = scans;
    delete[] price; delete[] owner; delete[] stack;
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) return -1;
    return 0;
}
