/*
 * Jacobi (synchronous) epsilon-scaling auction, minimize cost.
 * All currently unassigned persons bid simultaneously based on the same prices;
 * then prices and assignments update together. Far fewer rounds than GS,
 * each round is one full matrix scan (or only unassigned rows).
 *
 * Conflict resolution: if several persons bid for the same object, the one
 * with the highest bid increment wins (standard Jacobi auction).
 */
#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <cstdio>
#include <vector>

extern "C" int jacobi(const double* __restrict C, int n, int* __restrict rowsol, int* rounds_out) {
    double* price = new double[n]();
    int* owner = new int[n];
    double* bid_inc = new double[n];
    int* bidder = new int[n];
    int* unassigned = new int[n];
    double* bestv = new double[n];
    double* secondv = new double[n];
    int* jbest = new int[n];

    double cmax = -1e300, cmin = 1e300;
    int step = std::max(1, n/40);
    for (int i = 0; i < n; i += step) {
        const double* row = C + (int64_t)i*n;
        for (int j = 0; j < n; j += step) {
            double c = row[j];
            if (c > cmax) cmax = c;
            if (c < cmin) cmin = c;
        }
    }
    double eps = (cmax - cmin) / 4.0;
    const double eps_final = 1e-10;
    int rounds = 0;
    int phases = 0;

    while (phases < 25) {
        ++phases;
        for (int j = 0; j < n; ++j) owner[j] = -1;
        for (int i = 0; i < n; ++i) rowsol[i] = -1;
        int nu = n;
        for (int i = 0; i < n; ++i) unassigned[i] = i;

        int guard = n * 4; // Jacobi should converge in O(n) rounds worst, usually far less
        while (nu > 0 && guard-- > 0) {
            ++rounds;
            for (int j = 0; j < n; ++j) { bid_inc[j] = -1.0; bidder[j] = -1; }
            for (int t = 0; t < nu; ++t) {
                int i = unassigned[t];
                const double* row = C + (int64_t)i * n;
                double best = -1e300, second = -1e300;
                int jb = 0;
                for (int j = 0; j < n; ++j) {
                    double val = -row[j] - price[j];
                    if (val > best) { second = best; best = val; jb = j; }
                    else if (val > second) second = val;
                }
                double inc = best - second + eps;
                if (inc > bid_inc[jb]) { bid_inc[jb] = inc; bidder[jb] = i; }
            }
            // apply bids
            int nu2 = 0;
            // mark who got assigned this round
            // persons who bid but lost stay unassigned; persons displaced become unassigned
            uint8_t* got = new uint8_t[n];
            std::memset(got, 0, n);
            for (int j = 0; j < n; ++j) if (bidder[j] != -1) {
                price[j] += bid_inc[j];
                int prev = owner[j];
                if (prev != -1) rowsol[prev] = -1;
                owner[j] = bidder[j];
                rowsol[bidder[j]] = j;
                got[bidder[j]] = 1;
            }
            for (int t = 0; t < nu; ++t) {
                int i = unassigned[t];
                if (!got[i]) unassigned[nu2++] = i;
            }
            // displaced previous owners
            for (int j = 0; j < n; ++j) {
                // previous owners already have rowsol cleared if displaced; collect them
            }
            for (int i = 0; i < n; ++i) {
                if (rowsol[i] < 0) {
                    // might already be in unassigned list
                }
            }
            // rebuild unassigned cleanly
            nu2 = 0;
            for (int i = 0; i < n; ++i) if (rowsol[i] < 0) unassigned[nu2++] = i;
            nu = nu2;
            delete[] got;
        }
        if (eps <= eps_final) break;
        eps *= 0.25;
        if (eps < eps_final) eps = eps_final;
    }
    if (rounds_out) *rounds_out = rounds;
    int rc = 0;
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) rc = -1;
    delete[] price; delete[] owner; delete[] bid_inc; delete[] bidder;
    delete[] unassigned; delete[] bestv; delete[] secondv; delete[] jbest;
    return rc;
}
