{"command":"cat > build/repair.cpp << 'EOF'
/*
 * kNN auction + local repair.
 *
 * 1. For each row, take k nearest columns (nth_element).
 * 2. Epsilon-scaling GS auction on that sparse graph to tiny eps.
 * 3. Check global eps-CS: for each person, scan all columns. If someone
 *    prefers a column outside their list by more than eps, add that column
 *    (and a few near-contenders) to their list and re-auction the affected
 *    persons. Repeat until everyone is globally happy.
 * 4. Because final eps is tiny and costs are generic, the assignment is the
 *    unique optimum.
 */
#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <cstdio>
#include <vector>
#include <cstdlib>

extern "C" int repair_solve(const double* __restrict C, int n, int k_init, int* __restrict rowsol, int* stats) {
    double* price = new double[n]();
    int* owner = new int[n];
    int* stack = new int[n];

    // dynamic adjacency: start with k_init, allow growth up to k_max
    int k_max = std::min(n, k_init * 4);
    int* knn = new int[(int64_t)n * k_max];
    double* knnc = new double[(int64_t)n * k_max];
    int* klen = new int[n];
    int* tmp = new int[n];

    for (int i = 0; i < n; ++i) {
        const double* row = C + (int64_t)i * n;
        for (int j = 0; j < n; ++j) tmp[j] = j;
        std::nth_element(tmp, tmp + k_init, tmp + n, [&](int a, int b){ return row[a] < row[b]; });
        // sort the k for slightly better locality? not necessary
        int* id = knn + (int64_t)i * k_max;
        double* cs = knnc + (int64_t)i * k_max;
        for (int t = 0; t < k_init; ++t) { id[t] = tmp[t]; cs[t] = row[tmp[t]]; }
        klen[i] = k_init;
    }

    auto auction_phase = [&](double eps, bool reset) -> int {
        if (reset) {
            for (int j = 0; j < n; ++j) owner[j] = -1;
            for (int i = 0; i < n; ++i) rowsol[i] = -1;
        }
        int top = 0;
        for (int i = 0; i < n; ++i) if (rowsol[i] < 0) stack[top++] = i;
        int guard = n * 80;
        int bids = 0;
        while (top > 0 && guard-- > 0) {
            int i = stack[--top];
            int len = klen[i];
            const int* id = knn + (int64_t)i * k_max;
            const double* cs = knnc + (int64_t)i * k_max;
            double best = -1e300, second = -1e300;
            int jbest = id[0];
            for (int t = 0; t < len; ++t) {
                double val = -cs[t] - price[id[t]];
                if (val > best) { second = best; best = val; jbest = id[t]; }
                else if (val > second) second = val;
            }
            if (second < -1e200) second = best - 1.0;
            price[jbest] += best - second + eps;
            int prev = owner[jbest];
            if (prev != -1) { rowsol[prev] = -1; stack[top++] = prev; }
            owner[jbest] = i;
            rowsol[i] = jbest;
            ++bids;
        }
        return bids;
    };

    // cost scale from first rows' knn
    double cmax = -1e300, cmin = 1e300;
    for (int i = 0; i < std::min(n, 30); ++i) {
        const double* cs = knnc + (int64_t)i * k_max;
        for (int t = 0; t < k_init; ++t) {
            if (cs[t] > cmax) cmax = cs[t];
            if (cs[t] < cmin) cmin = cs[t];
        }
    }
    double eps = std::max((cmax - cmin) / 4.0, 1e-4);
    const double eps_final = 1e-10;

    int phases = 0;
    // coarse phases on initial graph
    while (eps > 1e-3 && phases < 15) {
        auction_phase(eps, true);
        eps *= 0.2;
        ++phases;
    }

    int repairs = 0;
    int full_scans = 0;
    // refinement + repair loop
    for (int outer = 0; outer < 12; ++outer) {
        auction_phase(eps, true);
        // global check
        int unhappy = 0;
        for (int i = 0; i < n; ++i) {
            const double* row = C + (int64_t)i * n;
            // best over all columns
            double best = -1e300, second = -1e300;
            int jbest = 0;
            for (int j = 0; j < n; ++j) {
                double val = -row[j] - price[j];
                if (val > best) { second = best; best = val; jbest = j; }
                else if (val > second) second = val;
            }
            ++full_scans;
            int cur = rowsol[i];
            double curval = (cur >= 0) ? (-row[cur] - price[cur]) : -1e300;
            // happy if current is within eps of best (eps-CS)
            if (best - curval > eps * 1.01) {
                // add jbest if missing
                int len = klen[i];
                int* id = knn + (int64_t)i * k_max;
                double* cs = knnc + (int64_t)i * k_max;
                bool found = false;
                for (int t = 0; t < len; ++t) if (id[t] == jbest) { found = true; break; }
                if (!found && len < k_max) {
                    id[len] = jbest;
                    cs[len] = row[jbest];
                    klen[i] = len + 1;
                    ++repairs;
                }
                // unassign so they rebid
                if (cur >= 0) { owner[cur] = -1; rowsol[i] = -1; }
                ++unhappy;
            }
        }
        if (unhappy == 0) {
            if (eps <= eps_final) break;
            eps *= 0.2;
            if (eps < eps_final) eps = eps_final;
        }
        // else loop again at same eps with expanded lists; don't reset prices
        // but auction_phase resets assignment. That's OK, prices kept.
    }

    if (stats) { stats[0] = repairs; stats[1] = full_scans; stats[2] = phases; }
    int rc = 0;
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) rc = -1;
    delete[] price; delete[] owner; delete[] stack;
    delete[] knn; delete[] knnc; delete[] klen; delete[] tmp;
    return rc;
}
