                    // force rebid by unassigning
                    owner[cur] = -1; rowsol[i] = -1;
                }
                ++unhappy;
            }
        }
        if (unhappy == 0) break;
        run_auction_from_unassigned(eps_final);
    }

    if (stats) { stats[0] = repairs; stats[1] = scans; stats[2] = phases; }
    int rc = 0;
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) rc = -1;
    delete[] price; delete[] owner; delete[] stack; delete[] inlist; delete[] tmp;
