/*
 * Assignment via epsilon-scaling auction on a dynamic kNN graph,
 * with incremental global best tracking.
 *
 * Each person stores best_val / best_j / second_val computed at a price snapshot,
 * plus the price generation. Prices are monotonically increasing and each price[j]
 * has a version. We recompute a person's global best only when one of their
 * candidate prices changed... still need global.
 *
 * Cheaper global check: a person is unhappy only if some column's price dropped
 * relative to them, but prices only rise, so values only fall. Once a person is
 * eps-CS happy, they stay happy until THEIR object's price rises (they get
 * displaced) or eps shrinks. So we only need to full-scan a person when:
 *   - they are unassigned, or
 *   - eps decreased since their last check, or
 *   - their assigned object's price increased since last check.
 * After initial convergence, subsequent checks are only of displaced persons
 * plus one scan per person per eps phase. That's ~8 phases * 600 scans = 4800
 * scans * 0.7us = 3.4ms plus sparse auction. Acceptable if we cut phases.
 *
 * Plan: 4 eps phases (0.05, 1e-3, 1e-6, 1e-10), k_init=32.
 * Full scan only at end of each phase for unhappy detection, and only add edges
 * then rebid. Target < 5ms.
 */
#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <cstdio>
#include <vector>

extern "C" int fast_solve(const double* __restrict C, int n, int k_init, int* __restrict rowsol) {
    double* price = new double[n]();
    int* owner = new int[n];
    int* stack = new int[n];
    uint8_t* inlist = new uint8_t[(size_t)n * n];
    std::memset(inlist, 0, (size_t)n * n);

    std::vector<std::vector<int>> knn(n);
    std::vector<std::vector<double>> knnc(n);
    int* tmp = new int[n];

    for (int i = 0; i < n; ++i) {
        const double* row = C + (int64_t)i * n;
        for (int j = 0; j < n; ++j) tmp[j] = j;
        std::nth_element(tmp, tmp + k_init, tmp + n, [&](int a, int b){ return row[a] < row[b]; });
        knn[i].reserve(k_init + 8);
        knnc[i].reserve(k_init + 8);
        for (int t = 0; t < k_init; ++t) {
            knn[i].push_back(tmp[t]);
            knnc[i].push_back(row[tmp[t]]);
            inlist[(size_t)i * n + tmp[t]] = 1;
        }
    }

    auto run = [&](double eps) -> int {
        int top = 0;
        for (int i = 0; i < n; ++i) if (rowsol[i] < 0) stack[top++] = i;
        int guard = n * 200;
        int bids = 0;
        while (top > 0 && --guard >= 0) {
            int i = stack[--top];
            if (rowsol[i] >= 0) continue;
            auto& id = knn[i];
            auto& cs = knnc[i];
            int len = (int)id.size();
            double best = -1e300, second = -1e300;
            int jbest = id[0];
            for (int t = 0; t < len; ++t) {
                double val = -cs[t] - price[id[t]];
                if (val > best) { second = best; best = val; jbest = id[t]; }
                else if (val > second) second = val;
            }
            if (second < -1e200) second = best - 1.0;
            price[jbest] += best - second + eps;
            int prev = owner[jbest];
            if (prev != -1 && prev != i) { rowsol[prev] = -1; stack[top++] = prev; }
            owner[jbest] = i;
            rowsol[i] = jbest;
            ++bids;
        }
        return bids;
    };

    auto add_edge = [&](int i, int j) {
        if (inlist[(size_t)i * n + j]) return;
        inlist[(size_t)i * n + j] = 1;
        knn[i].push_back(j);
        knnc[i].push_back(C[(int64_t)i * n + j]);
    };

    // find global best column for person i under current prices
    auto global_best = [&](int i, int& jbest) -> double {
        const double* row = C + (int64_t)i * n;
        double best = -1e300; jbest = 0;
        for (int j = 0; j < n; ++j) {
            double val = -row[j] - price[j];
            if (val > best) { best = val; jbest = j; }
        }
        return best;
    };

    for (int j = 0; j < n; ++j) owner[j] = -1;
    for (int i = 0; i < n; ++i) rowsol[i] = -1;

    // eps schedule: few phases
    double schedule[] = {5e-2, 1e-3, 2e-5, 5e-7, 1e-8, 2e-10, 1e-11};
    int ns = 7;
    for (int pi = 0; pi < ns; ++pi) {
        double eps = schedule[pi];
        // a few repair rounds at this eps
        for (int round = 0; round < 6; ++round) {
            run(eps);
            int unhappy = 0;
            for (int i = 0; i < n; ++i) {
                int jb; double best = global_best(i, jb);
                int cur = rowsol[i];
                double curval = -1e300;
                if (cur >= 0) curval = -C[(int64_t)i * n + cur] - price[cur];
                if (cur < 0 || best - curval > eps + 1e-15) {
                    add_edge(i, jb);
                    if (cur >= 0) { owner[cur] = -1; rowsol[i] = -1; }
                    ++unhappy;
                }
            }
            if (unhappy == 0) break;
        }
    }

    delete[] price; delete[] owner; delete[] stack; delete[] inlist; delete[] tmp;
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) return -1;
    return 0;
}
