{"command":"cat > build/fr.cpp << 'EOF'
/*
 * Forward-reverse auction on a symmetric kNN graph (row kNN union column kNN),
 * epsilon scaling down to ~0. The reverse auction is what lets us reach the
 * exact optimum at a relatively large epsilon (Bertsekas), so we may not need
 * eps=1e-12.
 *
 * Symmetric kNN: edge (i,j) exists if j is among k nearest of i OR i is among
 * k nearest of j. For geometric matching in the unit square this contains the
 * optimum for moderate k (mutual near neighbors). We'll verify.
 *
 * If the sparse graph has no perfect matching, return -1.
 */
#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <cstdio>
#include <vector>

extern "C" int fr_solve(const double* __restrict C, int n, int k, int* __restrict rowsol) {
    // build symmetric knn
    std::vector<std::vector<int>> adj(n);
    std::vector<std::vector<double>> adjc(n);
    uint8_t* has = new uint8_t[(size_t)n * n]();
    int* tmp = new int[n];

    auto add = [&](int i, int j, double c) {
        size_t p = (size_t)i * n + j;
        if (has[p]) return;
        has[p] = 1;
        adj[i].push_back(j);
        adjc[i].push_back(c);
    };

    for (int i = 0; i < n; ++i) {
        const double* row = C + (int64_t)i * n;
        for (int j = 0; j < n; ++j) tmp[j] = j;
        std::nth_element(tmp, tmp + k, tmp + n, [&](int a, int b){ return row[a] < row[b]; });
        for (int t = 0; t < k; ++t) add(i, tmp[t], row[tmp[t]]);
    }
    // column kNN: j's k nearest rows = for each column, k smallest C[i,j]
    // That's another n * nth_element over columns — columns are strided. Do it.
    for (int j = 0; j < n; ++j) {
        for (int i = 0; i < n; ++i) tmp[i] = i;
        std::nth_element(tmp, tmp + k, tmp + n, [&](int a, int b){
            return C[(int64_t)a * n + j] < C[(int64_t)b * n + j];
        });
        for (int t = 0; t < k; ++t) {
            int i = tmp[t];
            add(i, j, C[(int64_t)i * n + j]);
        }
    }

    double* price = new double[n]();      // object prices
    double* profit = new double[n]();     // person profits (for reverse) = best value
    int* owner = new int[n];
    int* stack = new int[n];
    for (int j = 0; j < n; ++j) owner[j] = -1;
    for (int i = 0; i < n; ++i) rowsol[i] = -1;

    auto forward = [&](double eps) -> int {
        for (int j = 0; j < n; ++j) owner[j] = -1;
        int top = 0;
        for (int i = 0; i < n; ++i) { rowsol[i] = -1; stack[top++] = i; }
        int guard = n * 100;
        int bids = 0;
        while (top > 0 && --guard >= 0) {
            int i = stack[--top];
            auto& id = adj[i];
            auto& cs = adjc[i];
            int len = (int)id.size();
            if (len == 0) return -1;
            double best = -1e300, second = -1e300;
            int jbest = id[0];
            for (int t = 0; t < len; ++t) {
                double val = -cs[t] - price[id[t]];
                if (val > best) { second = best; best = val; jbest = id[t]; }
                else if (val > second) second = val;
            }
            if (second < -1e200) second = best - 1.0;
            double inc = best - second + eps;
            price[jbest] += inc;
            profit[i] = second - eps; // after bid, person's profit becomes second-eps? 
            // actually after price increase, value of jbest = best - inc = second - eps
            int prev = owner[jbest];
            if (prev != -1) { rowsol[prev] = -1; stack[top++] = prev; }
            owner[jbest] = i;
            rowsol[i] = jbest;
            ++bids;
        }
        if (guard < 0) return -1;
        return bids;
    };

    double cmax = -1e300, cmin = 1e300;
    for (int i = 0; i < std::min(n, 30); ++i)
        for (double c : adjc[i]) { if (c>cmax) cmax=c; if (c<cmin) cmin=c; }
    double eps = std::max((cmax-cmin)/4.0, 1e-3);
    const double eps_final = 1e-9;

    int phase = 0;
    while (phase < 25) {
        int b = forward(eps);
        if (b < 0) { delete[] has; delete[] tmp; delete[] price; delete[] profit; delete[] owner; delete[] stack; return -2; }
        ++phase;
        if (eps <= eps_final) break;
        eps *= 0.2;
        if (eps < eps_final) eps = eps_final;
    }

    delete[] has; delete[] tmp; delete[] price; delete[] profit; delete[] owner; delete[] stack;
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) return -1;
    return 0;
}
