        for (int j = 0; j < n; ++j) owner[j] = -1;
        int top = 0;
        for (int i = 0; i < n; ++i) { rowsol[i] = -1; stack[top++] = i; }
        int guard = n * 150;
        while (top > 0 && --guard >= 0) {
            int i = stack[--top];
            auto& id = adj[i];
            auto& cs = adjc[i];
            int len = (int)id.size();
            double best = -1e300, second = -1e300;
            int jbest = id[0];
            for (int t = 0; t < len; ++t) {
                double val = -cs[t] - price[id[t]];
                if (val > best) { second = best; best = val; jbest = id[t]; }
                else if (val > second) second = val;
            }
            if (second < -1e200) second = best - 1.0;
            price[jbest] += best - second + eps;
            int prev = owner[jbest];
            if (prev != -1) { rowsol[prev] = -1; stack[top++] = prev; }
            owner[jbest] = i;
            rowsol[i] = jbest;
        }
        if (guard < 0) return -1;
        return 0;
    };

    double cmax = 1.0, cmin = 0.0;
    double eps = (cmax - cmin) / 4.0;
    int phase = 0;
    int rc = 0;
    while (phase < 20) {
        rc = forward(eps);
        if (rc < 0) break;
        ++phase;
        if (eps <= eps_final) break;
        eps *= 0.2;
        if (eps < eps_final) eps = eps_final;
    }
    delete[] has; delete[] tmp; delete[] price; delete[] owner; delete[] stack;
    if (rc < 0) return -2;
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) return -1;
    return 0;
}
