{"command":"cat > build/lapjv_clean.cpp << 'EOF'
/*
 * Dense LAPJV (Jonker-Volgenant), double precision.
 * Structure follows the published algorithm and the widely used C implementation
 * by Roy Jonker (magic-software / public domain lapjv). Adapted to doubles.
 *
 * x[i] = column matched to row i
 * y[j] = row matched to column j
 * u[i], v[j] duals, reduced cost = C[i,j] - u[i] - v[j] >= 0
 */
#include <cstdint>
#include <cstring>
#include <cmath>
#include <algorithm>
#include <cstdio>
#include <cstdlib>

static constexpr double BIG = 1e18;

extern "C" int lapjv_d(const double* __restrict C, int n, int* __restrict x, int* n_aug) {
    int* y = (int*)malloc(sizeof(int) * n);
    double* u = (double*)malloc(sizeof(double) * n);
    double* v = (double*)malloc(sizeof(double) * n);
    int* free_rows = (int*)malloc(sizeof(int) * n);
    int* pred = (int*)malloc(sizeof(int) * n);
    double* d = (double*)malloc(sizeof(double) * n);
    uint8_t* scanned = (uint8_t*)malloc(n);

    for (int i = 0; i < n; ++i) { x[i] = -1; y[i] = -1; u[i] = 0.0; v[i] = 0.0; }

    // COLUMN REDUCTION
    for (int j = n - 1; j >= 0; --j) {
        double m = C[j];
        int im = 0;
        for (int i = 1; i < n; ++i) {
            double c = C[(int64_t)i * n + j];
            if (c < m) { m = c; im = i; }
        }
        v[j] = m;
        if (x[im] == -1) { x[im] = j; y[j] = im; }
    }
    int f = 0;
    for (int i = 0; i < n; ++i) {
        if (x[i] == -1) free_rows[f++] = i;
        else u[i] = C[(int64_t)i * n + x[i]] - v[x[i]];
    }

    // REDUCTION TRANSFER
    int f2 = 0;
    int* free2 = (int*)malloc(sizeof(int) * n);
    for (int t = 0; t < f; ++t) {
        int i = free_rows[t];
        const double* row = C + (int64_t)i * n;
        double m1 = BIG, m2 = BIG;
        int j1 = 0;
        for (int j = 0; j < n; ++j) {
            double r = row[j] - v[j];
            if (r < m2) {
                if (r >= m1) m2 = r;
                else { m2 = m1; m1 = r; j1 = j; }
            }
        }
        u[i] = m1;
        if (m2 > m1) { // unique
            int i0 = y[j1];
            if (i0 < 0 || u[i0] > m1) {
                if (i0 >= 0) { x[i0] = -1; free2[f2++] = i0; }
                x[i] = j1; y[j1] = i;
                continue;
            }
        }
        free2[f2++] = i;
    }
    f = 0;
    for (int t = 0; t < f2; ++t) if (x[free2[t]] < 0) free_rows[f++] = free2[t];

    // AUGMENTING ROW REDUCTION (2 passes)
    for (int pass = 0; pass < 2; ++pass) {
        int head = 0, tail = f;
        while (head < tail) {
            int i = free_rows[head++];
            if (x[i] >= 0) continue;
            const double* row = C + (int64_t)i * n;
            double m1 = BIG, m2 = BIG;
            int j1 = 0;
            for (int j = 0; j < n; ++j) {
                double r = row[j] - v[j];
                if (r < m2) {
                    if (r >= m1) m2 = r;
                    else { m2 = m1; m1 = r; j1 = j; }
                }
            }
            if (m2 > m1) v[j1] -= (m2 - m1);
            int i0 = y[j1];
            if (i0 >= 0) {
                if (!(m2 > m1)) { free2[f2++] = i; continue; } // can't steal; defer
                x[i0] = -1;
                free_rows[tail++] = i0;
            }
            x[i] = j1; y[j1] = i;
            u[i] = m2 > m1 ? m2 : m1;
        }
        // rebuild free
        f = 0;
        for (int i = 0; i < n; ++i) if (x[i] < 0) free_rows[f++] = i;
    }

    int aug = 0;
    // SHORTEST AUGMENTING PATH
    for (int t = 0; t < f; ++t) {
        int freerow = free_rows[t];
        if (x[freerow] >= 0) continue;
        const double* row = C + (int64_t)freerow * n;
        std::memset(scanned, 0, n);
        for (int j = 0; j < n; ++j) {
            d[j] = row[j] - v[j] - u[freerow];
            pred[j] = freerow;
        }
        int endcol = -1;
        while (true) {
            double h = BIG; int jb = -1;
            for (int j = 0; j < n; ++j) if (!scanned[j] && d[j] < h) { h = d[j]; jb = j; }
            if (jb < 0) { endcol = -1; break; }
            scanned[jb] = 1;
            int i0 = y[jb];
            if (i0 < 0) { endcol = jb; break; }
            const double* r2 = C + (int64_t)i0 * n;
            double base = r2[jb] - v[jb] - u[i0];
            double hb = h - base;
            for (int j = 0; j < n; ++j) if (!scanned[j]) {
                double nd = hb + r2[j] - v[j] - u[i0];
                if (nd < d[j]) { d[j] = nd; pred[j] = i0; }
            }
        }
        if (endcol < 0) { aug = -1; break; }
        // dual update
        double dend = d[endcol];
        for (int j = 0; j < n; ++j) if (scanned[j]) v[j] += d[j] - dend;
        u[freerow] += dend;
        // augment
        int j = endcol;
        while (true) {
            int i0 = pred[j];
            y[j] = i0;
            std::swap(j, x[i0]);
            if (i0 == freerow) break;
        }
        ++aug;
    }

    if (n_aug) *n_aug = aug;
    free(y); free(u); free(v); free(free_rows); free(pred); free(d); free(scanned); free(free2);
    for (int i = 0; i < n; ++i) if (x[i] < 0) return -1;
    return aug < 0 ? -1 : 0;
}
