{"command":"cat > build/sap_fast.cpp << 'EOF'
/*
 * Primal-dual shortest augmenting path with:
 *  - column reduction initialization
 *  - a per-row kNN candidate list used as the ONLY edges considered first
 *  - if augmentation fails, k grows
 * This is the earlier correct SAP (lap2) which matched exactly, plus an
 * indexed scan: maintain columns in a binary heap of reduced distances,
 * initialized lazily.
 *
 * For geometric costs the alternating paths are short. We exploit that by
 * scanning a kNN list of the current row instead of all columns, and only
 * falling back to a full scan to find the next closest unscanned column
 * when the heap of candidate improvements is empty... 
 *
 * Simpler speedup that is correct: BLOCK the min-finding scan.
 * n=600, ~300 augmentations, average path length L.
 * If L is small (geometric), total min-scans are 300*L not 300*600.
 * Measure L by instrumenting.
 */
#include <cstdint>
#include <cstring>
#include <algorithm>
#include <cstdio>
#include <cstdlib>

extern "C" int sap_instrumented(const double* C, int n, int* rowsol, int* stats) {
    double* v = (double*)calloc(n, sizeof(double));
    double* d = (double*)malloc(sizeof(double)*n);
    int* colsol = (int*)malloc(sizeof(int)*n);
    int* pred = (int*)malloc(sizeof(int)*n);
    uint8_t* in_tree = (uint8_t*)malloc(n);
    int* freer = (int*)malloc(sizeof(int)*n);

    for (int i = 0; i < n; ++i) { rowsol[i] = -1; colsol[i] = -1; }

    for (int j = n-1; j >= 0; --j) {
        double m = C[j]; int im = 0;
        for (int i = 1; i < n; ++i) {
            double c = C[(int64_t)i*n+j];
            if (c < m) { m = c; im = i; }
        }
        v[j] = m;
        if (rowsol[im] == -1) { rowsol[im] = j; colsol[j] = im; }
    }
    int nf = 0;
    for (int i = 0; i < n; ++i) if (rowsol[i] == -1) freer[nf++] = i;

    long long scans = 0;      // number of min-finding scans
    long long inner = 0;      // number of column updates
    int max_path = 0;

    for (int fi = 0; fi < nf; ++fi) {
        int f = freer[fi];
        const double* row = C + (int64_t)f * n;
        for (int j = 0; j < n; ++j) {
            d[j] = row[j] - v[j];
            pred[j] = f;
            in_tree[j] = 0;
        }
        int path_len = 0;
        int endcol = -1;
        while (true) {
            ++scans;
            double h = 1e300; int jb = -1;
            for (int j = 0; j < n; ++j) if (!in_tree[j] && d[j] < h) { h = d[j]; jb = j; }
            in_tree[jb] = 1;
            int i0 = colsol[jb];
            if (i0 < 0) { endcol = jb; break; }
            ++path_len;
            const double* r2 = C + (int64_t)i0 * n;
            double hb = h - (r2[jb] - v[jb]);
            for (int j = 0; j < n; ++j) if (!in_tree[j]) {
                double nd = hb + r2[j] - v[j];
                if (nd < d[j]) { d[j] = nd; pred[j] = i0; }
                ++inner;
            }
        }
        if (path_len > max_path) max_path = path_len;
        double dend = d[endcol];
        for (int j = 0; j < n; ++j) if (in_tree[j]) v[j] += d[j] - dend;
        int j = endcol;
        while (true) {
            int i0 = pred[j];
            colsol[j] = i0;
            int jn = rowsol[i0];
            rowsol[i0] = j;
            if (i0 == f) break;
            j = jn;
        }
    }
    stats[0] = nf;
    stats[1] = (int)scans;
    stats[2] = max_path;
    stats[3] = (int)(inner / 1000);
    free(v); free(d); free(colsol); free(pred); free(in_tree); free(freer);
    return 0;
}
