{"command":"cat > build/hk.cpp << 'EOF'
/*
 * Threshold matching: include each row's k cheapest edges, find maximum matching
 * by DFS augmenting paths (Hopcroft-style with greedy start). Grow k until
 * perfect. Then the matching is NOT necessarily optimal — this only tests
 * how fast a perfect matching in the kNN graph can be found, as a lower bound
 * on a cost-scaling approach that repeatedly matches.
 */
#include <cstdint>
#include <cstring>
#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <vector>

extern "C" int knn_matching(const double* C, int n, int k, int* rowsol, int* stats) {
    // build kNN
    int* adj = (int*)malloc(sizeof(int) * (size_t)n * k);
    int* tmp = (int*)malloc(sizeof(int) * n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) tmp[j] = j;
        const double* row = C + (int64_t)i * n;
        std::nth_element(tmp, tmp + k, tmp + n, [&](int a, int b){ return row[a] < row[b]; });
        int* id = adj + (size_t)i * k;
        for (int t = 0; t < k; ++t) id[t] = tmp[t];
    }
    int* matchR = (int*)malloc(sizeof(int) * n); // col -> row
    for (int j = 0; j < n; ++j) matchR[j] = -1;
    for (int i = 0; i < n; ++i) rowsol[i] = -1;

    // greedy
    uint8_t* used = (uint8_t*)calloc(n, 1);
    for (int i = 0; i < n; ++i) {
        int* id = adj + (size_t)i * k;
        for (int t = 0; t < k; ++t) {
            int j = id[t];
            if (!used[j]) { used[j] = 1; rowsol[i] = j; matchR[j] = i; break; }
        }
    }
    free(used);

    int* vis = (int*)malloc(sizeof(int) * n);
    int stamp = 0;
    std::memset(vis, 0, sizeof(int)*n);

    auto dfs = [&](auto& self, int i) -> bool {
        int* id = adj + (size_t)i * k;
        for (int t = 0; t < k; ++t) {
            int j = id[t];
            if (vis[j] == stamp) continue;
            vis[j] = stamp;
            int i0 = matchR[j];
            if (i0 < 0 || self(self, i0)) {
                matchR[j] = i;
                rowsol[i] = j;
                return true;
            }
        }
        return false;
    };

    int aug = 0;
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) {
        ++stamp;
        if (dfs(dfs, i)) ++aug;
    }
    int matched = 0;
    for (int i = 0; i < n; ++i) if (rowsol[i] >= 0) ++matched;
    stats[0] = matched;
    stats[1] = aug;
    free(adj); free(tmp); free(matchR); free(vis);
    return matched == n ? 0 : -1;
}
