/*
 * Jonker-Volgenant algorithm, double-precision adaptation of the
 * classic integer implementation (R. Jonker, "A shortest augmenting path
 * algorithm for dense and sparse linear assignment problems", Computing 1987).
 *
 * The control flow (column reduction, reduction transfer, augmenting row
 * reduction, then Dijkstra augmentation with a ready/todo column partition)
 * follows that paper. Integer arithmetic is replaced by doubles.
 */
#include <cstdint>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <algorithm>
#include <cstdio>

static const double FP_EPS = 1e-12;

extern "C" int lapjv(const double* assigncost, int dim, int* rowsol, int* stats) {
    int unassignedfound;
    int i, imin, numfree = 0, prvnumfree, f, i0, k, freerow;
    int j, j1, j2 = 0, endofpath = 0, last = 0, low, up;
    double min = 0, h, umin, usubmin, v2;
    int* colsol = (int*)malloc(sizeof(int) * dim);
    double* d = (double*)malloc(sizeof(double) * dim);
    int* free = (int*)malloc(sizeof(int) * dim);
    int* pred = (int*)malloc(sizeof(int) * dim);
    int* collist = (int*)malloc(sizeof(int) * dim);
    int* matches = (int*)malloc(sizeof(int) * dim);
    double* u = (double*)calloc(dim, sizeof(double));
    double* v = (double*)calloc(dim, sizeof(double));

    auto cost = [&](int r, int c) -> double { return assigncost[(int64_t)r * dim + c]; };

    for (i = 0; i < dim; i++) matches[i] = 0;

    // COLUMN REDUCTION
    for (j = dim - 1; j >= 0; j--) {
        min = cost(0, j);
        imin = 0;
        for (i = 1; i < dim; i++)
            if (cost(i, j) < min) { min = cost(i, j); imin = i; }
        v[j] = min;
        if (++matches[imin] == 1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            colsol[j] = -1;
        }
    }
    for (i = 0; i < dim; i++)
        if (matches[i] == 0) free[numfree++] = i;
        else if (matches[i] == 1) {
            j1 = rowsol[i];
            min = 1e300;
            for (j = 0; j < dim; j++)
                if (j != j1 && cost(i, j) - v[j] < min) min = cost(i, j) - v[j];
            v[j1] = cost(i, j1) - min;
        }

    // REDUCTION TRANSFER
    for (int loopcnt = 0; loopcnt < 2; loopcnt++) {
        int k = 0;
        prvnumfree = numfree;
        numfree = 0;
        while (k < prvnumfree) {
            i = free[k++];
            umin = cost(i, 0) - v[0];
            j1 = 0;
            usubmin = 1e300;
            for (j = 1; j < dim; j++) {
                h = cost(i, j) - v[j];
                if (h < usubmin) {
                    if (h >= umin) { usubmin = h; j2 = j; }
                    else { usubmin = umin; umin = h; j2 = j1; j1 = j; }
                }
            }
            i0 = colsol[j1];
            if (umin < usubmin) v[j1] = cost(i, j1) - usubmin;  // = v[j1] - (usubmin-umin)
            else if (i0 >= 0) { j1 = j2; i0 = colsol[j2]; }
            if (i0 >= 0) {
                if (umin < usubmin) free[--k] = i0;
                else free[numfree++] = i;
            }
            rowsol[i] = j1;
            colsol[j1] = i;
        }
    }

    // AUGMENTING ROW REDUCTION
    for (f = 0; f < numfree; f++) {
        freerow = free[f];
        // Dijkstra
        for (j = 0; j < dim; j++) {
            d[j] = cost(freerow, j) - v[j];
            pred[j] = freerow;
            collist[j] = j;
        }
        low = 0;
        up = 0;
        unassignedfound = 0;
        do {
            if (up == low) {
                last = low - 1;
                min = d[collist[up++]];
                for (k = up; k < dim; k++) {
                    j = collist[k];
                    h = d[j];
                    if (h <= min) {
                        if (h < min) { up = low; min = h; }
                        collist[k] = collist[up];
                        collist[up++] = j;
                    }
                }
                for (k = low; k < up; k++)
                    if (colsol[collist[k]] < 0) { endofpath = collist[k]; unassignedfound = 1; break; }
            }
            if (!unassignedfound) {
                j1 = collist[low];
                low++;
                i = colsol[j1];
                h = cost(i, j1) - v[j1] - min;
                for (k = up; k < dim; k++) {
                    j = collist[k];
                    v2 = cost(i, j) - v[j] - h;
                    if (v2 < d[j]) {
                        pred[j] = i;
                        if (v2 == min) {
                            if (colsol[j] < 0) { endofpath = j; unassignedfound = 1; break; }
                            else { collist[k] = collist[up]; collist[up++] = j; }
                        }
                        d[j] = v2;
                    }
                }
            }
        } while (!unassignedfound);

        // dual update
        for (k = 0; k <= last; k++) {
            j1 = collist[k];
            v[j1] += d[j1] - min;
        }
        // augment
        do {
            i = pred[endofpath];
            colsol[endofpath] = i;
            j1 = endofpath;
            endofpath = rowsol[i];
            rowsol[i] = j1;
        } while (i != freerow);
    }

    int matched = 0;
    for (i = 0; i < dim; i++) if (rowsol[i] >= 0 && rowsol[i] < dim) matched++;
    if (stats) { stats[0] = numfree; stats[1] = matched; }

    free(colsol); free(d); free(free); free(pred); free(collist); free(matches); free(u); free(v);
    return matched == dim ? 0 : -1;
}
