// Jonker-Volgenant, double, with safe reduction transfer (no infinite reinsertion)
// and epsilon-aware frontier test.
#include <cstdint>
#include <cstring>
#include <cstdlib>
#include <algorithm>
#include <cstdio>

extern "C" int lapjv2(const double* C, int dim, int* rowsol) {
    int* colsol = (int*)malloc(sizeof(int) * dim);
    double* d = (double*)malloc(sizeof(double) * dim);
    int* freer = (int*)malloc(sizeof(int) * dim);
    int* pred = (int*)malloc(sizeof(int) * dim);
    int* collist = (int*)malloc(sizeof(int) * dim);
    int* matches = (int*)calloc(dim, sizeof(int));
    double* v = (double*)calloc(dim, sizeof(double));

    auto cost = [&](int r, int c) -> double { return C[(int64_t)r * dim + c]; };

    for (int i = 0; i < dim; i++) rowsol[i] = -1;

    // COLUMN REDUCTION
    for (int j = dim - 1; j >= 0; j--) {
        double minv = cost(0, j);
        int imin = 0;
        for (int i = 1; i < dim; i++) {
            double c = cost(i, j);
            if (c < minv) { minv = c; imin = i; }
        }
        v[j] = minv;
        if (++matches[imin] == 1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            colsol[j] = -1;
        }
    }
    int numfree = 0;
    for (int i = 0; i < dim; i++) {
        if (matches[i] == 0) freer[numfree++] = i;
        else if (matches[i] == 1) {
            int j1 = rowsol[i];
            double minv = 1e300;
            for (int j = 0; j < dim; j++) if (j != j1) {
                double h = cost(i, j) - v[j];
                if (h < minv) minv = h;
            }
            v[j1] = cost(i, j1) - minv;
        }
    }

    // REDUCTION TRANSFER — one pass, no reinsertion (avoids float infinite loop)
    {
        int nf2 = 0;
        int* freer2 = (int*)malloc(sizeof(int) * dim);
        for (int t = 0; t < numfree; t++) {
            int i = freer[t];
            double umin = cost(i, 0) - v[0];
            int j1 = 0;
            double usubmin = 1e300;
            int j2 = 0;
            for (int j = 1; j < dim; j++) {
                double h = cost(i, j) - v[j];
                if (h < usubmin) {
                    if (h >= umin) { usubmin = h; j2 = j; }
                    else { usubmin = umin; umin = h; j2 = j1; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            if (umin < usubmin) {
                v[j1] = cost(i, j1) - usubmin;
            } else if (i0 >= 0) {
                j1 = j2;
                i0 = colsol[j2];
            }
            if (i0 >= 0) {
                // don't steal if it would require reinsertion loop; just stay free
                freer2[nf2++] = i;
                continue;
            }
            rowsol[i] = j1;
            colsol[j1] = i;
        }
        numfree = nf2;
        for (int t = 0; t < nf2; t++) freer[t] = freer2[t];
        ::free(freer2);
    }

    const double TOL = 1e-12;
    int aug_ok = 1;
    for (int f = 0; f < numfree; f++) {
        int freerow = freer[f];
        if (rowsol[freerow] >= 0) continue;
        for (int j = 0; j < dim; j++) {
            d[j] = cost(freerow, j) - v[j];
            pred[j] = freerow;
            collist[j] = j;
        }
        int low = 0, up = 0, last = 0;
        int unassignedfound = 0;
        int endofpath = -1;
        double minv = 0;
        int guard = dim * dim;
        while (!unassignedfound && guard-- > 0) {
            if (up == low) {
                last = low - 1;
                minv = d[collist[up++]];
                for (int k = up; k < dim; k++) {
                    int j = collist[k];
                    double h = d[j];
                    if (h <= minv + TOL) {
                        if (h < minv) { up = low; minv = h; }
                        collist[k] = collist[up];
                        collist[up++] = j;
                    }
                }
                for (int k = low; k < up; k++) {
                    if (colsol[collist[k]] < 0) {
                        endofpath = collist[k];
                        unassignedfound = 1;
                        break;
                    }
                }
            }
            if (!unassignedfound) {
                if (low >= dim) break;
                int j1 = collist[low];
                low++;
                int i = colsol[j1];
                if (i < 0) { endofpath = j1; unassignedfound = 1; break; }
                double h = cost(i, j1) - v[j1] - minv;
                for (int k = up; k < dim; k++) {
                    int j = collist[k];
                    double v2 = cost(i, j) - v[j] - h;
                    if (v2 < d[j]) {
                        pred[j] = i;
                        if (v2 <= minv + TOL) {
                            if (colsol[j] < 0) {
                                endofpath = j;
                                unassignedfound = 1;
                                d[j] = v2;
                                break;
                            } else {
                                collist[k] = collist[up];
                                collist[up++] = j;
                            }
                        }
                        d[j] = v2;
                    }
                }
            }
        }
        if (!unassignedfound || endofpath < 0) { aug_ok = 0; break; }
        for (int k = 0; k <= last; k++) {
            int j1 = collist[k];
            v[j1] += d[j1] - minv;
        }
        int i, j1;
        do {
            i = pred[endofpath];
            colsol[endofpath] = i;
            j1 = endofpath;
            endofpath = rowsol[i];
            rowsol[i] = j1;
        } while (i != freerow);
    }

    ::free(colsol); ::free(d); ::free(freer); ::free(pred); ::free(collist); ::free(matches); ::free(v);
    if (!aug_ok) return -1;
    for (int i = 0; i < dim; i++) if (rowsol[i] < 0) return -1;
    return 0;
}
