/*
 * Integer Jonker-Volgenant.
 * Adapted from the public-domain implementation by Roy Jonker (1987 algorithm),
 * the version circulated with the paper "A shortest augmenting path algorithm
 * for dense and sparse linear assignment problems".
 *
 * Costs are int64. BIG must exceed any feasible reduced cost.
 */
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <cstdio>
#include <algorithm>

using int64 = long long;

static const int64 BIG = (int64)1 << 60;

extern "C" int lapjv_int(const int64* assigncost, int dim, int* rowsol) {
    int i, imin, numfree = 0, prvnumfree, f, i0, k, freerow;
    int j, j1, j2, endofpath, last, low, up;
    int64 min, h, umin, usubmin, v2;
    int unassignedfound;

    int* colsol = (int*)malloc(sizeof(int) * dim);
    int64* d = (int64*)malloc(sizeof(int64) * dim);
    int* free_rows = (int*)malloc(sizeof(int) * dim);
    int* pred = (int*)malloc(sizeof(int) * dim);
    int* collist = (int*)malloc(sizeof(int) * dim);
    int* matches = (int*)calloc(dim, sizeof(int));
    int64* u = (int64*)calloc(dim, sizeof(int64));
    int64* v = (int64*)calloc(dim, sizeof(int64));

    auto cost = [&](int r, int c) -> int64 {
        return assigncost[(int64)r * dim + c];
    };

    for (i = 0; i < dim; i++) rowsol[i] = -1;

    // COLUMN REDUCTION
    for (j = dim - 1; j >= 0; j--) {
        min = cost(0, j);
        imin = 0;
        for (i = 1; i < dim; i++)
            if (cost(i, j) < min) { min = cost(i, j); imin = i; }
        v[j] = min;
        if (++matches[imin] == 1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else
            colsol[j] = -1;
    }
    for (i = 0; i < dim; i++)
        if (matches[i] == 0)
            free_rows[numfree++] = i;
        else if (matches[i] == 1) {
            j1 = rowsol[i];
            min = BIG;
            for (j = 0; j < dim; j++)
                if (j != j1 && (h = cost(i, j) - v[j]) < min) min = h;
            v[j1] = cost(i, j1) - min;
        }

    // REDUCTION TRANSFER
    int loopcnt = 0;
    do {
        loopcnt++;
        k = 0;
        prvnumfree = numfree;
        numfree = 0;
        while (k < prvnumfree) {
            i = free_rows[k];
            k++;
            umin = cost(i, 0) - v[0];
            j1 = 0;
            usubmin = BIG;
            for (j = 1; j < dim; j++) {
                h = cost(i, j) - v[j];
                if (h < usubmin) {
                    if (h >= umin) { usubmin = h; j2 = j; }
                    else { usubmin = umin; umin = h; j2 = j1; j1 = j; }
                }
            }
            i0 = colsol[j1];
            if (umin < usubmin)
                v[j1] = cost(i, j1) - usubmin;
            else if (i0 >= 0) {
                j1 = j2;
                i0 = colsol[j2];
            }
            if (i0 >= 0) {
                if (umin < usubmin)
                    free_rows[--k] = i0;
                else
                    free_rows[numfree++] = i;
            }
            rowsol[i] = j1;
            colsol[j1] = i;
        }
    } while (loopcnt < 2);

    // AUGMENTATION
    for (f = 0; f < numfree; f++) {
        freerow = free_rows[f];
        for (j = 0; j < dim; j++) {
            d[j] = cost(freerow, j) - v[j];
            pred[j] = freerow;
            collist[j] = j;
        }
        low = 0;
        up = 0;
        unassignedfound = 0;
        do {
            if (up == low) {
                last = low - 1;
                min = d[collist[up++]];
                for (k = up; k < dim; k++) {
                    j = collist[k];
                    h = d[j];
                    if (h <= min) {
                        if (h < min) {
                            up = low;
                            min = h;
                        }
                        collist[k] = collist[up];
                        collist[up++] = j;
                    }
                }
                for (k = low; k < up; k++)
                    if (colsol[collist[k]] < 0) {
                        endofpath = collist[k];
                        unassignedfound = 1;
                        break;
                    }
            }
            if (!unassignedfound) {
                j1 = collist[low];
                low++;
                i = colsol[j1];
                h = cost(i, j1) - v[j1] - min;
                for (k = up; k < dim; k++) {
                    j = collist[k];
                    v2 = cost(i, j) - v[j] - h;
                    if (v2 < d[j]) {
                        pred[j] = i;
                        if (v2 == min) {
                            if (colsol[j] < 0) {
                                endofpath = j;
                                unassignedfound = 1;
                                break;
                            } else {
                                collist[k] = collist[up];
                                collist[up++] = j;
                            }
                        }
                        d[j] = v2;
                    }
                }
            }
        } while (!unassignedfound);

        for (k = 0; k <= last; k++) {
            j1 = collist[k];
            v[j1] = v[j1] + d[j1] - min;
        }
        do {
            i = pred[endofpath];
            colsol[endofpath] = i;
            j1 = endofpath;
            endofpath = rowsol[i];
            rowsol[i] = j1;
        } while (i != freerow);
    }

    ::free(colsol); ::free(d); ::free(free_rows); ::free(pred);
    ::free(collist); ::free(matches); ::free(u); ::free(v);
    return 0;
}
