#include <cstdint>
#include <cstring>
#include <algorithm>
#include <cstdio>
#include <cstdlib>

// Correct SAP finish + augmenting row reduction initialization.
// Returns 0 and the assignment. stats: [nfree_after_col, nfree_after_arr, augs]

extern "C" int jv_arr(const double* C, int n, int* rowsol, int* stats) {
    double* v = (double*)calloc(n, sizeof(double));
    double* d = (double*)malloc(sizeof(double) * n);
    int* colsol = (int*)malloc(sizeof(int) * n);
    int* pred = (int*)malloc(sizeof(int) * n);
    uint8_t* in_tree = (uint8_t*)malloc(n);
    int* freer = (int*)malloc(sizeof(int) * n * 2);

    for (int i = 0; i < n; ++i) { rowsol[i] = -1; colsol[i] = -1; }

    // column reduction
    for (int j = n - 1; j >= 0; --j) {
        double m = C[j];
        int im = 0;
        for (int i = 1; i < n; ++i) {
            double c = C[(int64_t)i * n + j];
            if (c < m) { m = c; im = i; }
        }
        v[j] = m;
        if (rowsol[im] == -1) { rowsol[im] = j; colsol[j] = im; }
    }
    int nf = 0;
    for (int i = 0; i < n; ++i) if (rowsol[i] == -1) freer[nf++] = i;
    int nf_col = nf;

    // Augmenting row reduction, 2 passes.
    // For each free row: find min and second min reduced cost.
    // If the min column is free, take it.
    // If unique min (m1 < m2) and column taken, lower v so reduced equals m2, steal column, free previous owner.
    for (int pass = 0; pass < 2; ++pass) {
        int head = 0, tail = nf;
        while (head < tail) {
            int i = freer[head++];
            if (rowsol[i] >= 0) continue;
            const double* row = C + (int64_t)i * n;
            double m1 = 1e300, m2 = 1e300;
            int j1 = 0;
            for (int j = 0; j < n; ++j) {
                double r = row[j] - v[j];
                if (r < m2) {
                    if (r >= m1) m2 = r;
                    else { m2 = m1; m1 = r; j1 = j; }
                }
            }
            int i0 = colsol[j1];
            bool unique = m1 < m2 - 1e-15;
            if (i0 < 0) {
                rowsol[i] = j1;
                colsol[j1] = i;
                if (unique) v[j1] -= (m2 - m1);
            } else if (unique) {
                v[j1] -= (m2 - m1);
                rowsol[i0] = -1;
                freer[tail++] = i0;
                rowsol[i] = j1;
                colsol[j1] = i;
            }
            // else not unique and taken: stay free (will be caught in rebuild)
        }
        nf = 0;
        for (int i = 0; i < n; ++i) if (rowsol[i] < 0) freer[nf++] = i;
    }
    int nf_arr = nf;

    // SAP for remaining free rows (correct dual update)
    int augs = 0;
    for (int fi = 0; fi < nf; ++fi) {
        int f = freer[fi];
        if (rowsol[f] >= 0) continue;
        const double* row = C + (int64_t)f * n;
        for (int j = 0; j < n; ++j) {
            d[j] = row[j] - v[j];
            pred[j] = f;
            in_tree[j] = 0;
        }
        int endcol = -1;
        while (true) {
            double h = 1e300; int jb = -1;
            for (int j = 0; j < n; ++j) if (!in_tree[j] && d[j] < h) { h = d[j]; jb = j; }
            if (jb < 0) break;
            in_tree[jb] = 1;
            int i0 = colsol[jb];
            if (i0 < 0) { endcol = jb; break; }
            const double* r2 = C + (int64_t)i0 * n;
            double hb = h - (r2[jb] - v[jb]);
            for (int j = 0; j < n; ++j) if (!in_tree[j]) {
                double nd = hb + r2[j] - v[j];
                if (nd < d[j]) { d[j] = nd; pred[j] = i0; }
            }
        }
        if (endcol < 0) {
            stats[0] = nf_col; stats[1] = nf_arr; stats[2] = -1;
            ::free(v); ::free(d); ::free(colsol); ::free(pred); ::free(in_tree); ::free(freer);
            return -1;
        }
        double dend = d[endcol];
        for (int j = 0; j < n; ++j) if (in_tree[j]) v[j] += d[j] - dend;
        int j = endcol;
        while (true) {
            int i0 = pred[j];
            colsol[j] = i0;
            int jn = rowsol[i0];
            rowsol[i0] = j;
            if (i0 == f) break;
            j = jn;
        }
        ++augs;
    }
    stats[0] = nf_col; stats[1] = nf_arr; stats[2] = augs;
    ::free(v); ::free(d); ::free(colsol); ::free(pred); ::free(in_tree); ::free(freer);
    for (int i = 0; i < n; ++i) if (rowsol[i] < 0) return -1;
    return 0;
}
