import ctypes, numpy as np, time
from pathlib import Path
from ot.lp import emd_wrap
from reference import Task
lib = ctypes.CDLL(str(Path("build/jv_arr.so").resolve()))
lib.jv_arr.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_int), ctypes.POINTER(ctypes.c_int)]
lib.jv_arr.restype = ctypes.c_int
task = Task()
n=600
exact=0
for seed in range(6):
    p = task.generate_problem(n=n, random_seed=seed+1)
    a = np.ascontiguousarray(p["source_weights"], dtype=np.float64)
    b = np.ascontiguousarray(p["target_weights"], dtype=np.float64)
    M = np.ascontiguousarray(p["cost_matrix"], dtype=np.float64)
    G, cost, *_ = emd_wrap.emd_c(a,b,M,100000,1)
    cols = np.argmax(G,1).astype(np.int32)
    x = np.empty(n, dtype=np.int32)
    st = np.zeros(3, dtype=np.int32)
    t0=time.perf_counter()
    rc = lib.jv_arr(M.ctypes.data_as(ctypes.POINTER(ctypes.c_double)), n,
                    x.ctypes.data_as(ctypes.POINTER(ctypes.c_int)),
                    st.ctypes.data_as(ctypes.POINTER(ctypes.c_int)))
    dt=(time.perf_counter()-t0)*1000
    ok = rc==0 and np.array_equal(x, cols)
    cd = M[np.arange(n), x].sum()/n if rc==0 else float('nan')
    print(f"seed {seed} rc={rc} exact={ok} costdiff={cd-cost:.3e} free_col={st[0]} free_arr={st[1]} augs={st[2]} {dt:.1f} ms")
    exact += int(ok)
print("exact", exact)
EOF"}
